	"os"
	"strconv"
	"strings"
	"time"
)

func main() {
	addr := os.Args[1]
	verbose := len(os.Args) > 2
	h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		if verbose {
			fmt.Fprintf(os.Stderr, "%s %s %s %v %q\n", r.Proto, r.Method, r.URL.String(), r.Header, string(body))
		}
		if strings.HasPrefix(r.URL.Path, "/sleep/") {
