use std::time::Duration;

/// Parse `-n` values like `200`, `10k`, `1.5m`.
pub fn parse_n_requests(s: &str) -> Result<usize, String> {
    let bytes = s.as_bytes();
    if let Some(last) = bytes.last() {
        let mult = match *last {
            b'k' | b'K' => Some(1_000.0),
            b'm' | b'M' => Some(1_000_000.0),
            _ => None,
        };
        if let Some(mult) = mult {
            let prefix = &s[..s.len() - 1];
            let v: f64 = prefix.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
            return Ok((v * mult) as usize);
        }
    }
    s.parse::<usize>().map_err(|e| e.to_string())
}

pub fn parse_duration_arg(s: &str) -> Result<Duration, String> {
    crate::duration::parse_duration(s).map_err(|e| e.to_string())
}

pub fn parse_method(s: &str) -> Result<String, String> {
    if s.is_empty() || !s.bytes().all(is_token_char) {
        return Err("invalid HTTP method".to_string());
    }
    Ok(s.to_string())
}

fn is_token_char(b: u8) -> bool {
    matches!(b,
        b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~'
        | b'0'..=b'9' | b'a'..=b'z' | b'A'..=b'Z')
}

pub fn is_valid_header_name(name: &str) -> bool {
    !name.is_empty() && name.bytes().all(is_token_char)
}

pub fn is_valid_header_value(value: &[u8]) -> bool {
    value.iter().all(|&b| b == b'\t' || (b >= 0x20 && b != 0x7f))
}

#[derive(Clone, Debug)]
pub struct Header {
    pub name: String,
    pub value: String,
}

pub fn parse_header(s: &str) -> Result<Header, String> {
    let (name, value) = s.split_once(':').ok_or_else(|| "Parse header".to_string())?;
    if !is_valid_header_name(name) {
        return Err("invalid HTTP header name".to_string());
    }
    let value = value.trim();
    if !is_valid_header_value(value.as_bytes()) {
        return Err("failed to parse header value".to_string());
    }
    Ok(Header {
        name: name.to_ascii_lowercase(),
        value: value.to_string(),
    })
}

pub fn parse_url(s: &str) -> Result<url::Url, String> {
    url::Url::parse(s).map_err(|e| e.to_string())
}

#[derive(Clone, Debug)]
pub struct ConnectToEntry {
    pub requested_host: String,
    pub requested_port: u16,
    pub target_host: String,
    pub target_port: u16,
}

pub fn parse_connect_to(s: &str) -> Result<ConnectToEntry, String> {
    let parts: Vec<&str> = s.rsplitn(4, ':').collect();
    if parts.len() != 4 {
        return Err("syntax for --connect-to is host:port:target_host:target_port".to_string());
    }
    let target_port_s = parts[0];
    let target_host = parts[1];
    let requested_port_s = parts[2];
    let requested_host = parts[3];
    let requested_port: u16 = requested_port_s
        .parse()
        .map_err(|e| format!("requested port must be an u16, but got {}: {}", requested_port_s, e))?;
    let target_port: u16 = target_port_s
        .parse()
        .map_err(|e| format!("target port must be an u16, but got {}: {}", target_port_s, e))?;
    Ok(ConnectToEntry {
        requested_host: requested_host.to_string(),
        requested_port,
        target_host: target_host.to_string(),
        target_port,
    })
}
