//! A humantime-compatible duration parser (with fractional support).
use std::fmt;
use std::time::Duration;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit { unit: String, value: u64 },
    NumberOverflow,
    Empty,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidCharacter(off) => write!(f, "invalid character at {}", off),
            Error::NumberExpected(off) => write!(f, "expected number at {}", off),
            Error::UnknownUnit { unit, value } => {
                if unit.is_empty() {
                    write!(f, "time unit needed, for example {0}sec or {0}ms", value)
                } else {
                    write!(
                        f,
                        "unknown time unit {:?}, supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)",
                        unit
                    )
                }
            }
            Error::NumberOverflow => f.write_str(
                "number is too large or cannot be represented without a lack of precision (values below 1ns are not supported)",
            ),
            Error::Empty => f.write_str("value was empty"),
        }
    }
}

impl std::error::Error for Error {}

struct Parser<'a> {
    iter: std::str::Chars<'a>,
    src: &'a str,
    current: (u64, u64),
}

#[derive(Default, Clone, Copy)]
struct Frac {
    numerator: u64,
    digits: u32,
    dot_off: usize,
}

fn unit_nanos(unit: &str) -> Option<u64> {
    Some(match unit {
        "nanos" | "nsec" | "ns" => 1,
        "usec" | "us" | "µs" => 1_000,
        "millis" | "msec" | "ms" => 1_000_000,
        "seconds" | "second" | "secs" | "sec" | "s" => 1_000_000_000,
        "minutes" | "minute" | "min" | "mins" | "m" => 60 * 1_000_000_000,
        "hours" | "hour" | "hr" | "hrs" | "h" => 3600 * 1_000_000_000,
        "days" | "day" | "d" => 86400 * 1_000_000_000,
        "weeks" | "week" | "w" => 86400 * 7 * 1_000_000_000,
        "months" | "month" | "M" => 2_630_016 * 1_000_000_000,
        "years" | "year" | "y" => 31_557_600 * 1_000_000_000,
        _ => return None,
    })
}

impl<'a> Parser<'a> {
    fn off(&self) -> usize {
        self.src.len() - self.iter.as_str().len()
    }

    fn parse_first_char(&mut self) -> Result<Option<u64>, Error> {
        let off = self.off();
        for c in self.iter.by_ref() {
            match c {
                '0'..='9' => return Ok(Some(c as u64 - '0' as u64)),
                c if c.is_whitespace() => continue,
                _ => return Err(Error::NumberExpected(off)),
            }
        }
        Ok(None)
    }

    fn parse_unit(&mut self, n: u64, frac: Option<Frac>, start: usize, end: usize) -> Result<(), Error> {
        let unit = &self.src[start..end];
        let nanos_per_unit = match unit_nanos(unit) {
            Some(v) => v,
            None => {
                return Err(Error::UnknownUnit {
                    unit: unit.to_string(),
                    value: n,
                })
            }
        };
        if let Some(frac) = frac {
            if frac.digits == 0 {
                return Err(Error::InvalidCharacter(frac.dot_off));
            }
        }
        // integer part
        let (mut sec, mut nsec) = if nanos_per_unit >= 1_000_000_000 {
            let secs_per_unit = nanos_per_unit / 1_000_000_000;
            (n.checked_mul(secs_per_unit).ok_or(Error::NumberOverflow)?, 0u64)
        } else {
            let total = n.checked_mul(nanos_per_unit).ok_or(Error::NumberOverflow)?;
            (total / 1_000_000_000, total % 1_000_000_000)
        };
        if let Some(frac) = frac {
            let pow = 10u64.checked_pow(frac.digits).ok_or(Error::NumberOverflow)?;
            let prod = frac
                .numerator
                .checked_mul(nanos_per_unit)
                .ok_or(Error::NumberOverflow)?;
            if prod % pow != 0 {
                return Err(Error::NumberOverflow);
            }
            let extra = prod / pow;
            sec = sec.checked_add(extra / 1_000_000_000).ok_or(Error::NumberOverflow)?;
            nsec += extra % 1_000_000_000;
        }
        let mut nsec = self.current.1.checked_add(nsec).ok_or(Error::NumberOverflow)?;
        if nsec >= 1_000_000_000 {
            sec = sec.checked_add(nsec / 1_000_000_000).ok_or(Error::NumberOverflow)?;
            nsec %= 1_000_000_000;
        }
        sec = self.current.0.checked_add(sec).ok_or(Error::NumberOverflow)?;
        self.current = (sec, nsec);
        Ok(())
    }

    fn parse(mut self) -> Result<Duration, Error> {
        let mut n = self.parse_first_char()?.ok_or(Error::Empty)?;
        let mut frac: Option<Frac> = None;
        'outer: loop {
            let mut off = self.off();
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        let d = c as u64 - '0' as u64;
                        match &mut frac {
                            Some(f) => {
                                f.numerator = f
                                    .numerator
                                    .checked_mul(10)
                                    .and_then(|x| x.checked_add(d))
                                    .ok_or(Error::NumberOverflow)?;
                                f.digits += 1;
                            }
                            None => {
                                n = n
                                    .checked_mul(10)
                                    .and_then(|x| x.checked_add(d))
                                    .ok_or(Error::NumberOverflow)?;
                            }
                        }
                    }
                    '.' => {
                        if frac.is_some() {
                            return Err(Error::InvalidCharacter(off));
                        }
                        frac = Some(Frac {
                            numerator: 0,
                            digits: 0,
                            dot_off: off,
                        });
                    }
                    c if c.is_whitespace() => {}
                    'a'..='z' | 'A'..='Z' | 'µ' => break,
                    _ => return Err(Error::InvalidCharacter(off)),
                }
                off = self.off();
            }
            let start = off;
            let mut off = self.off();
            while let Some(c) = self.iter.next() {
                match c {
                    '0'..='9' => {
                        self.parse_unit(n, frac, start, off)?;
                        n = c as u64 - '0' as u64;
                        frac = None;
                        continue 'outer;
                    }
                    c if c.is_whitespace() => break,
                    'a'..='z' | 'A'..='Z' | 'µ' => {}
                    _ => return Err(Error::InvalidCharacter(off)),
                }
                off = self.off();
            }
            self.parse_unit(n, frac, start, off)?;
            frac = None;
            n = match self.parse_first_char()? {
                Some(n) => n,
                None => return Ok(Duration::new(self.current.0, self.current.1 as u32)),
            };
        }
    }
}

pub fn parse_duration(s: &str) -> Result<Duration, Error> {
    Parser {
        iter: s.chars(),
        src: s,
        current: (0, 0),
    }
    .parse()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(parse_duration("1.5s").unwrap(), Duration::from_millis(1500));
        assert_eq!(parse_duration("1h30m").unwrap(), Duration::from_secs(5400));
        assert_eq!(parse_duration("1 . 5s").unwrap(), Duration::from_millis(1500));
        assert!(parse_duration("1.s").is_err());
        assert_eq!(parse_duration("1.s").unwrap_err().to_string(), "invalid character at 1");
        assert_eq!(parse_duration("1.5.5s").unwrap_err().to_string(), "invalid character at 3");
        assert_eq!(parse_duration("1.5").unwrap_err().to_string(), "time unit needed, for example 1sec or 1ms");
        assert!(parse_duration("1.50000000000s").is_err());
        assert!(parse_duration("0.5ns").is_err());
        assert!(parse_duration("1.000000001s").is_ok());
        assert!(parse_duration("1.0000000001s").is_err());
    }
}
EOF
echo ok"}

