//! Random string generation from a regular expression (rand_regex-like).
use rand::seq::SliceRandom;
use rand::Rng;
use regex_syntax::hir::{Class, Hir, HirKind};
use std::fmt;

#[derive(Debug)]
pub enum Error {
    Syntax(regex_syntax::Error),
    Anchor,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Syntax(e) => write!(f, "{}", e),
            Error::Anchor => f.write_str("anchor is not supported"),
        }
    }
}

impl std::error::Error for Error {}

#[derive(Debug, Clone)]
pub struct RandRegex {
    hir: Hir,
    max_repeat: u32,
}

fn check_supported(hir: &Hir) -> Result<(), Error> {
    match hir.kind() {
        HirKind::Look(_) => Err(Error::Anchor),
        HirKind::Repetition(rep) => check_supported(&rep.sub),
        HirKind::Capture(c) => check_supported(&c.sub),
        HirKind::Concat(v) | HirKind::Alternation(v) => {
            for h in v {
                check_supported(h)?;
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

impl RandRegex {
    pub fn compile(pattern: &str, max_repeat: u32) -> Result<Self, Error> {
        let hir = regex_syntax::Parser::new()
            .parse(pattern)
            .map_err(Error::Syntax)?;
        check_supported(&hir)?;
        Ok(RandRegex { hir, max_repeat })
    }

    pub fn generate<R: Rng + ?Sized>(&self, rng: &mut R) -> String {
        let mut out = String::new();
        self.gen_hir(&self.hir, rng, &mut out);
        out
    }

    fn gen_hir<R: Rng + ?Sized>(&self, hir: &Hir, rng: &mut R, out: &mut String) {
        match hir.kind() {
            HirKind::Empty => {}
            HirKind::Literal(lit) => {
                if let Ok(s) = std::str::from_utf8(&lit.0) {
                    out.push_str(s);
                } else {
                    for &b in lit.0.iter() {
                        out.push(b as char);
                    }
                }
            }
            HirKind::Class(Class::Unicode(cls)) => {
                let total: u64 = cls
                    .ranges()
                    .iter()
                    .map(|r| (r.end() as u64) - (r.start() as u64) + 1)
                    .sum();
                if total == 0 {
                    return;
                }
                let mut idx = rng.gen_range(0..total);
                for r in cls.ranges() {
                    let len = (r.end() as u64) - (r.start() as u64) + 1;
                    if idx < len {
                        let cp = r.start() as u64 + idx;
                        if let Some(c) = char::from_u32(cp as u32) {
                            out.push(c);
                        }
                        return;
                    }
                    idx -= len;
                }
            }
            HirKind::Class(Class::Bytes(cls)) => {
                let total: u32 = cls
                    .ranges()
                    .iter()
                    .map(|r| (r.end() as u32) - (r.start() as u32) + 1)
                    .sum();
                if total == 0 {
                    return;
                }
                let mut idx = rng.gen_range(0..total);
                for r in cls.ranges() {
                    let len = (r.end() as u32) - (r.start() as u32) + 1;
                    if idx < len {
                        let b = (r.start() as u32 + idx) as u8;
                        out.push(b as char);
                        return;
                    }
                    idx -= len;
                }
            }
            HirKind::Look(_) => {}
            HirKind::Repetition(rep) => {
                let min = rep.min;
                let max = rep.max.unwrap_or(rep.min.saturating_add(self.max_repeat));
                let n = if max > min { rng.gen_range(min..=max) } else { min };
                for _ in 0..n {
                    self.gen_hir(&rep.sub, rng, out);
                }
            }
            HirKind::Capture(c) => self.gen_hir(&c.sub, rng, out),
            HirKind::Concat(v) => {
                for h in v {
                    self.gen_hir(h, rng, out);
                }
            }
            HirKind::Alternation(v) => {
                if let Some(h) = v.choose(rng) {
                    self.gen_hir(h, rng, out);
                }
            }
        }
    }
}
