use crate::rand_regex::RandRegex;
use rand::seq::SliceRandom;
use rand::Rng;
use std::fmt;
use std::io::BufRead;
use url::Url;

#[derive(Debug)]
pub enum UrlGenerator {
    Static(Url),
    MultiStatic(Vec<Url>),
    Dynamic(RandRegex),
}

#[derive(Debug)]
pub enum UrlGeneratorError {
    Parse(url::ParseError, String),
}

impl fmt::Display for UrlGeneratorError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UrlGeneratorError::Parse(e, url) => write!(f, "{}, generated url: {}", e, url),
        }
    }
}

impl std::error::Error for UrlGeneratorError {}

impl UrlGenerator {
    pub fn new_multi_static(urls: Vec<Url>) -> Self {
        assert!(!urls.is_empty());
        UrlGenerator::MultiStatic(urls)
    }

    pub fn new_static(url: Url) -> Self {
        UrlGenerator::Static(url)
    }

    pub fn new_dynamic(regex: RandRegex) -> Self {
        UrlGenerator::Dynamic(regex)
    }

    pub fn from_file(path: &str) -> Result<Self, anyhow::Error> {
        let file = std::fs::File::open(path)?;
        let reader = std::io::BufReader::new(file);
        let mut urls = Vec::new();
        for line in reader.lines().map_while(Result::ok) {
            if line.trim().is_empty() {
                continue;
            }
            urls.push(Url::parse(&line)?);
        }
        Ok(Self::new_multi_static(urls))
    }

    pub fn generate<R: Rng + ?Sized>(&self, rng: &mut R) -> Result<Url, UrlGeneratorError> {
        match self {
            UrlGenerator::Static(url) => Ok(url.clone()),
            UrlGenerator::MultiStatic(urls) => Ok(urls.choose(rng).unwrap().clone()),
            UrlGenerator::Dynamic(regex) => {
                let generated = regex.generate(rng);
                Url::parse(&generated).map_err(|e| UrlGeneratorError::Parse(e, generated))
            }
        }
    }

    /// Returns the URL when it is static (not generated per request).
    pub fn static_url(&self) -> Option<&Url> {
        match self {
            UrlGenerator::Static(url) => Some(url),
            _ => None,
        }
    }
}
