            UrlGenerator::Static(url) => Ok(url.clone()),
            UrlGenerator::MultiStatic(urls) => Ok(urls.choose(rng).unwrap().clone()),
            UrlGenerator::Dynamic(regex) => {
                let generated = regex.generate(rng);
                Url::parse(&generated).map_err(|e| UrlGeneratorError::Parse(e, generated))
            }
        }
    }

    /// Returns the URL when it is static (not generated per request).
    pub fn static_url(&self) -> Option<&Url> {
        match self {
            UrlGenerator::Static(url) => Some(url),
            _ => None,
        }
    }
}
