pub struct TlsConfig {
    pub insecure: bool,
    pub cacert: Option<String>,
    pub cert: Option<String>,
    pub key: Option<String>,
    pub alpn_h2: bool,
}

pub struct TlsContext {
    ctx: *mut SSL_CTX,
}

unsafe impl Send for TlsContext {}
unsafe impl Sync for TlsContext {}

fn openssl_error_string() -> String {
    unsafe {
        let e = ERR_peek_last_error();
        if e == 0 {
            return "unknown TLS error".to_string();
        }
        let mut buf = [0 as c_char; 256];
        ERR_error_string_n(e, buf.as_mut_ptr(), buf.len());
        let s = std::ffi::CStr::from_ptr(buf.as_ptr()).to_string_lossy().into_owned();
        ERR_clear_error();
        s
    }
}

impl TlsContext {
    pub fn new(config: &TlsConfig) -> Result<Self, String> {
        unsafe {
            OPENSSL_init_ssl(0, ptr::null());
            let ctx = SSL_CTX_new(TLS_client_method());
            if ctx.is_null() {
                return Err(openssl_error_string());
            }
            SSL_CTX_ctrl(ctx, SSL_CTRL_SET_MIN_PROTO_VERSION, TLS1_2_VERSION, ptr::null_mut());
            if config.insecure {
                SSL_CTX_set_verify(ctx, SSL_VERIFY_NONE, ptr::null());
            } else {
                SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, ptr::null());
            }
            SSL_CTX_set_default_verify_paths(ctx);
            if let Some(cacert) = &config.cacert {
                let c = CString::new(cacert.as_str()).unwrap();
                if SSL_CTX_load_verify_locations(ctx, c.as_ptr(), ptr::null()) != 1 {
                    let e = openssl_error_string();
                    SSL_CTX_free(ctx);
                    return Err(e);
                }
            }
            if let (Some(cert), Some(key)) = (&config.cert, &config.key) {
                let c = CString::new(cert.as_str()).unwrap();
                if SSL_CTX_use_certificate_chain_file(ctx, c.as_ptr()) != 1 {
                    let e = openssl_error_string();
                    SSL_CTX_free(ctx);
                    return Err(e);
                }
                let k = CString::new(key.as_str()).unwrap();
                if SSL_CTX_use_PrivateKey_file(ctx, k.as_ptr(), SSL_FILETYPE_PEM) != 1 {
                    let e = openssl_error_string();
                    SSL_CTX_free(ctx);
                    return Err(e);
                }
            }
            let protos: &[u8] = if config.alpn_h2 {
                b"\x02h2\x08http/1.1"
            } else {
                b"\x08http/1.1"
            };
            SSL_CTX_set_alpn_protos(ctx, protos.as_ptr(), protos.len() as c_uint);
            Ok(TlsContext { ctx })
        }
    }

    /// Perform a TLS handshake over an already connected socket.
    pub fn connect(&self, fd: RawFd, hostname: &str, verify_hostname: bool) -> Result<TlsStream, TlsError> {
        unsafe {
            ERR_clear_error();
            let ssl = SSL_new(self.ctx);
            if ssl.is_null() {
                return Err(TlsError::Other(openssl_error_string()));
            }
            SSL_set_fd(ssl, fd);
            // SNI: only for non-IP hostnames
            let is_ip = hostname.parse::<std::net::IpAddr>().is_ok();
            let host_c = CString::new(hostname.trim_start_matches('[').trim_end_matches(']')).unwrap();
            if !is_ip {
                SSL_ctrl(
                    ssl,
                    SSL_CTRL_SET_TLSEXT_HOSTNAME,
                    TLSEXT_NAMETYPE_host_name,
                    host_c.as_ptr() as *mut c_void,
                );
            }
            if verify_hostname {
                SSL_set1_host(ssl, host_c.as_ptr());
            }
            let ret = SSL_connect(ssl);
            if ret != 1 {
                let err = SSL_get_error(ssl, ret);
                let verify = SSL_get_verify_result(ssl);
                let result = if verify != X509_V_OK {
                    Err(TlsError::Verify(verify_error_message(ssl, verify, hostname)))
                } else {
                    match err {
                        SSL_ERROR_SYSCALL | SSL_ERROR_WANT_READ | SSL_ERROR_WANT_WRITE => {
                            let os = io::Error::last_os_error();
                            if ERR_peek_last_error() != 0 {
                                Err(TlsError::Other(map_ssl_error(openssl_error_string())))
                            } else if os.raw_os_error() == Some(0) || ret == 0 {
                                Err(TlsError::Io(io::Error::new(
                                    io::ErrorKind::UnexpectedEof,
                                    "connection closed before message completed",
                                )))
                            } else {
                                Err(TlsError::Io(os))
                            }
                        }
                        SSL_ERROR_ZERO_RETURN => Err(TlsError::Io(io::Error::new(
                            io::ErrorKind::UnexpectedEof,
                            "connection closed before message completed",
                        ))),
                        _ => Err(TlsError::Other(map_ssl_error(openssl_error_string()))),
                    }
                };
                SSL_free(ssl);
                return result;
            }
            let mut data: *const u8 = ptr::null();
            let mut len: c_uint = 0;
            SSL_get0_alpn_selected(ssl, &mut data, &mut len);
            let alpn = if data.is_null() || len == 0 {
                None
            } else {
                Some(std::slice::from_raw_parts(data, len as usize).to_vec())
            };
            Ok(TlsStream { ssl, alpn })
        }
    }
}

fn map_ssl_error(s: String) -> String {
    // Map OpenSSL error strings to rustls-like messages where possible.
    if s.contains("wrong version number")
        || s.contains("packet length too long")
        || s.contains("unknown protocol")
        || s.contains("http request")
        || s.contains("unexpected message")
    {
        "received corrupt message of type InvalidContentType".to_string()
    } else if s.contains("unexpected eof") {
        "peer closed connection without sending TLS close_notify: https://docs.rs/rustls/latest/rustls/manual/_03_connecting/index.html#unexpected-eof".to_string()
    } else if s.contains("alert handshake failure") || s.contains("sslv3 alert") || s.contains("tlsv1 alert") {
        let alert = s
            .rsplit(':')
            .next()
            .unwrap_or("")
            .trim()
            .to_string();
        format!("received fatal alert: {}", to_camel(&alert))
    } else {
        s
    }
}

fn to_camel(s: &str) -> String {
    let s = s.trim_start_matches("sslv3 alert ").trim_start_matches("tlsv1 alert ");
    s.split(|c: char| c == ' ' || c == '_')
        .map(|w| {
            let mut c = w.chars();
            match c.next() {
                Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect()
}

unsafe fn verify_error_message(ssl: *mut SSL, verify: c_long, hostname: &str) -> String {
    const X509_V_ERR_CERT_NOT_YET_VALID: c_long = 9;
    const X509_V_ERR_CERT_HAS_EXPIRED: c_long = 10;
    const X509_V_ERR_DEPTH_ZERO_SELF_SIGNED_CERT: c_long = 18;
    const X509_V_ERR_SELF_SIGNED_CERT_IN_CHAIN: c_long = 19;
    const X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT_LOCALLY: c_long = 20;
    const X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT: c_long = 2;
    const X509_V_ERR_CERT_REVOKED: c_long = 23;
    const X509_V_ERR_HOSTNAME_MISMATCH: c_long = 62;
    const X509_V_ERR_IP_ADDRESS_MISMATCH: c_long = 64;
    const X509_V_ERR_INVALID_CA: c_long = 24;
    const X509_V_ERR_CERT_SIGNATURE_FAILURE: c_long = 7;
    match verify {
        X509_V_ERR_DEPTH_ZERO_SELF_SIGNED_CERT
        | X509_V_ERR_SELF_SIGNED_CERT_IN_CHAIN
        | X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT_LOCALLY
        | X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT => "invalid peer certificate: UnknownIssuer".to_string(),
        X509_V_ERR_CERT_HAS_EXPIRED => "invalid peer certificate: Expired".to_string(),
        X509_V_ERR_CERT_NOT_YET_VALID => "invalid peer certificate: NotValidYet".to_string(),
        X509_V_ERR_CERT_REVOKED => "invalid peer certificate: Revoked".to_string(),
        X509_V_ERR_INVALID_CA => "invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string(),
        X509_V_ERR_CERT_SIGNATURE_FAILURE => "invalid peer certificate: BadSignature".to_string(),
        X509_V_ERR_HOSTNAME_MISMATCH | X509_V_ERR_IP_ADDRESS_MISMATCH => {
            let names = peer_cert_names(ssl);
            if names.is_empty() {
                format!(
                    "invalid peer certificate: certificate not valid for name \"{}\"; certificate is not valid for any names",
                    hostname
                )
            } else {
                format!(
                    "invalid peer certificate: certificate not valid for name \"{}\"; certificate is only valid for {}",
                    hostname,
                    names.join(" or ")
                )
            }
        }
        _ => {
            let s = X509_verify_cert_error_string(verify);
            let s = std::ffi::CStr::from_ptr(s).to_string_lossy().into_owned();
            format!("invalid peer certificate: {}", s)
        }
    }
}

unsafe fn peer_cert_names(ssl: *mut SSL) -> Vec<String> {
    let mut out = Vec::new();
    let cert = SSL_get1_peer_certificate(ssl);
    if cert.is_null() {
        return out;
    }
    let names = X509_get_ext_d2i(cert, NID_subject_alt_name, ptr::null_mut(), ptr::null_mut());
    if !names.is_null() {
        let n = OPENSSL_sk_num(names);
        for i in 0..n {
            let gn = OPENSSL_sk_value(names, i) as *const GENERAL_NAME;
            if gn.is_null() {
                continue;
            }
            let typ = (*gn).typ;
            let d = (*gn).d;
            if typ == GEN_DNS {
                let data = ASN1_STRING_get0_data(d);
                let len = ASN1_STRING_length(d);
                let s = std::slice::from_raw_parts(data, len as usize);
                out.push(format!("DnsName({:?})", String::from_utf8_lossy(s)));
            } else if typ == GEN_IPADD {
                let data = ASN1_STRING_get0_data(d);
                let len = ASN1_STRING_length(d);
                let s = std::slice::from_raw_parts(data, len as usize);
                if len == 4 {
                    out.push(format!("IpAddress({}.{}.{}.{})", s[0], s[1], s[2], s[3]));
                } else if len == 16 {
                    let mut segs = [0u16; 8];
                    for (i, seg) in segs.iter_mut().enumerate() {
                        *seg = ((s[i * 2] as u16) << 8) | s[i * 2 + 1] as u16;
                    }
                    out.push(format!("IpAddress({})", std::net::Ipv6Addr::from(segs)));
                }
            }
        }
        GENERAL_NAMES_free(names);
    }
    X509_free(cert);
    out
}

impl Drop for TlsContext {
    fn drop(&mut self) {
        unsafe { SSL_CTX_free(self.ctx) }
    }
}

#[derive(Debug)]
pub enum TlsError {
    Io(io::Error),
    Verify(String),
    Other(String),
}

impl std::fmt::Display for TlsError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TlsError::Io(e) => write!(f, "{}", e),
            TlsError::Verify(s) | TlsError::Other(s) => f.write_str(s),
        }
    }
}

pub struct TlsStream {
    ssl: *mut SSL,
    pub alpn: Option<Vec<u8>>,
}

unsafe impl Send for TlsStream {}

impl TlsStream {
    fn classify(&self, ret: c_int) -> io::Error {
        unsafe {
            let err = SSL_get_error(self.ssl, ret);
            match err {
                SSL_ERROR_ZERO_RETURN => io::Error::new(io::ErrorKind::UnexpectedEof, "tls closed"),
                SSL_ERROR_WANT_READ | SSL_ERROR_WANT_WRITE => {
                    let os = io::Error::last_os_error();
                    if os.kind() == io::ErrorKind::WouldBlock || os.kind() == io::ErrorKind::TimedOut {
                        os
                    } else {
                        io::Error::new(io::ErrorKind::WouldBlock, "tls would block")
                    }
                }
                SSL_ERROR_SYSCALL => {
                    let os = io::Error::last_os_error();
                    if ERR_peek_last_error() != 0 {
                        io::Error::new(io::ErrorKind::Other, map_ssl_error(openssl_error_string()))
                    } else if os.raw_os_error() == Some(0) {
                        io::Error::new(io::ErrorKind::UnexpectedEof, "tls eof")
                    } else {
                        os
                    }
                }
                _ => io::Error::new(io::ErrorKind::Other, map_ssl_error(openssl_error_string())),
            }
        }
    }
}

impl io::Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        unsafe {
            ERR_clear_error();
            let ret = SSL_read(self.ssl, buf.as_mut_ptr() as *mut c_void, buf.len().min(c_int::MAX as usize) as c_int);
            if ret > 0 {
                Ok(ret as usize)
            } else {
                let e = self.classify(ret);
                if e.kind() == io::ErrorKind::UnexpectedEof {
                    Ok(0)
                } else {
                    Err(e)
                }
            }
        }
    }
}

impl io::Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        unsafe {
            ERR_clear_error();
            let ret = SSL_write(self.ssl, buf.as_ptr() as *const c_void, buf.len().min(c_int::MAX as usize) as c_int);
            if ret > 0 {
                Ok(ret as usize)
            } else {
                Err(self.classify(ret))
            }
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl Drop for TlsStream {
    fn drop(&mut self) {
        unsafe {
            SSL_shutdown(self.ssl);
            SSL_free(self.ssl);
        }
    }
}
EOF
echo ok"}

