//! A small DNS resolver: /etc/hosts + UDP queries to the nameservers in /etc/resolv.conf.
use crate::parse::ConnectToEntry;
use rand::seq::SliceRandom;
use rand::Rng;
use std::collections::HashMap;
use std::fmt;
use std::net::{IpAddr, SocketAddr, UdpSocket};
use std::sync::Mutex;
use std::time::Duration;

#[derive(Debug, Clone)]
pub enum DnsError {
    Io(String),
    Timeout,
    NoRecords { name: String, qtype: &'static str },
    Message(String),
}

impl fmt::Display for DnsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DnsError::Io(e) => write!(f, "proto error: io error: {}", e),
            DnsError::Timeout => write!(f, "proto error: request timed out"),
            DnsError::NoRecords { name, qtype } => write!(
                f,
                "proto error: no record found for Query {{ name: Name(\"{}.\"), query_type: {}, query_class: IN }}",
                name.trim_end_matches('.'),
                qtype
            ),
            DnsError::Message(m) => write!(f, "proto error: {}", m),
        }
    }
}

impl std::error::Error for DnsError {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpStrategy {
    Both,
    Ipv4Only,
    Ipv6Only,
}

pub struct Resolver {
    strategy: IpStrategy,
    connect_to: Vec<ConnectToEntry>,
    hosts: Vec<(String, IpAddr)>,
    nameservers: Vec<SocketAddr>,
    cache: Mutex<HashMap<String, Vec<IpAddr>>>,
}

impl Resolver {
    pub fn new(strategy: IpStrategy, connect_to: Vec<ConnectToEntry>) -> Self {
        Resolver {
            strategy,
            connect_to,
            hosts: read_hosts(),
            nameservers: read_resolv_conf(),
            cache: Mutex::new(HashMap::new()),
        }
    }

    /// Apply --connect-to overrides. Returns (host, port) to actually connect to.
    pub fn connect_target<R: Rng + ?Sized>(&self, host: &str, port: u16, rng: &mut R) -> (String, u16) {
        let matches: Vec<&ConnectToEntry> = self
            .connect_to
            .iter()
            .filter(|e| e.requested_host == host && e.requested_port == port)
            .collect();
        if let Some(e) = matches.choose(rng) {
            (e.target_host.clone(), e.target_port)
        } else {
            (host.to_string(), port)
        }
    }

    pub fn has_connect_to(&self) -> bool {
        !self.connect_to.is_empty()
    }

    pub fn cache_lookup(&self, host: &str) -> Result<(), DnsError> {
        let addrs = self.resolve(host)?;
        self.cache.lock().unwrap().insert(host.to_string(), addrs);
        Ok(())
    }

    pub fn lookup(&self, host: &str) -> Result<Vec<IpAddr>, DnsError> {
        if let Some(v) = self.cache.lock().unwrap().get(host) {
            return Ok(v.clone());
        }
        self.resolve(host)
    }

    fn resolve(&self, host: &str) -> Result<Vec<IpAddr>, DnsError> {
        let bare = host.trim_start_matches('[').trim_end_matches(']');
        if let Ok(ip) = bare.parse::<IpAddr>() {
            return Ok(vec![ip]);
        }
        let name = host.trim_end_matches('.').to_ascii_lowercase();
        // /etc/hosts
        let from_hosts: Vec<IpAddr> = self
            .hosts
            .iter()
            .filter(|(n, ip)| *n == name && self.accept(ip))
            .map(|(_, ip)| *ip)
            .collect();
        if !from_hosts.is_empty() {
            return Ok(from_hosts);
        }
        let mut result = Vec::new();
        let mut last_err = None;
        let qtypes: &[(u16, &'static str)] = match self.strategy {
            IpStrategy::Both => &[(1, "A"), (28, "AAAA")],
            IpStrategy::Ipv4Only => &[(1, "A")],
            IpStrategy::Ipv6Only => &[(28, "AAAA")],
        };
        for (qtype, qname) in qtypes {
            match self.query(&name, *qtype) {
                Ok(mut v) => result.append(&mut v),
                Err(e) => {
                    if last_err.is_none() {
                        last_err = Some(match e {
                            DnsError::NoRecords { name, .. } => DnsError::NoRecords { name, qtype: qname },
                            other => other,
                        });
                    }
                }
            }
        }
        if result.is_empty() {
            Err(last_err.unwrap_or(DnsError::NoRecords {
                name,
                qtype: qtypes[0].1,
            }))
        } else {
            Ok(result)
        }
    }

    fn accept(&self, ip: &IpAddr) -> bool {
        match self.strategy {
            IpStrategy::Both => true,
            IpStrategy::Ipv4Only => ip.is_ipv4(),
            IpStrategy::Ipv6Only => ip.is_ipv6(),
        }
    }

    fn query(&self, name: &str, qtype: u16) -> Result<Vec<IpAddr>, DnsError> {
        if self.nameservers.is_empty() {
            return Err(DnsError::Message("no connections available".to_string()));
        }
        let mut last_err = None;
        for ns in &self.nameservers {
            for _attempt in 0..2 {
                match self.query_server(*ns, name, qtype) {
                    Ok(v) => return Ok(v),
                    Err(e) => {
                        let retry = matches!(e, DnsError::Timeout);
                        last_err = Some(e);
                        if !retry {
                            break;
                        }
                    }
                }
            }
        }
        Err(last_err.unwrap())
    }

    fn query_server(&self, ns: SocketAddr, name: &str, qtype: u16) -> Result<Vec<IpAddr>, DnsError> {
        let bind: SocketAddr = if ns.is_ipv4() {
            "0.0.0.0:0".parse().unwrap()
        } else {
            "[::]:0".parse().unwrap()
        };
        let sock = UdpSocket::bind(bind).map_err(|e| DnsError::Io(e.to_string()))?;
        sock.connect(ns).map_err(|e| DnsError::Io(e.to_string()))?;
        sock.set_read_timeout(Some(Duration::from_secs(5)))
            .map_err(|e| DnsError::Io(e.to_string()))?;
        let id: u16 = rand::thread_rng().gen();
        let msg = build_query(id, name, qtype);
        sock.send(&msg).map_err(|e| DnsError::Io(e.to_string()))?;
        let mut buf = [0u8; 4096];
        loop {
            let n = match sock.recv(&mut buf) {
                Ok(n) => n,
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock || e.kind() == std::io::ErrorKind::TimedOut => {
                    return Err(DnsError::Timeout)
                }
                Err(e) => return Err(DnsError::Io(e.to_string())),
            };
            let resp = &buf[..n];
            if resp.len() < 12 || u16::from_be_bytes([resp[0], resp[1]]) != id {
                continue;
            }
            return parse_response(resp, name, qtype);
        }
    }
}

fn build_query(id: u16, name: &str, qtype: u16) -> Vec<u8> {
    let mut msg = Vec::with_capacity(64);
    msg.extend_from_slice(&id.to_be_bytes());
    msg.extend_from_slice(&[0x01, 0x00]); // RD
    msg.extend_from_slice(&[0, 1, 0, 0, 0, 0, 0, 0]);
    for label in name.split('.') {
        if label.is_empty() {
            continue;
        }
        let bytes = label.as_bytes();
        msg.push(bytes.len().min(63) as u8);
        msg.extend_from_slice(&bytes[..bytes.len().min(63)]);
    }
    msg.push(0);
    msg.extend_from_slice(&qtype.to_be_bytes());
    msg.extend_from_slice(&[0, 1]);
    msg
}

fn skip_name(msg: &[u8], mut pos: usize) -> Option<usize> {
    loop {
        let len = *msg.get(pos)? as usize;
        if len == 0 {
            return Some(pos + 1);
        }
        if len & 0xC0 == 0xC0 {
            return Some(pos + 2);
        }
        pos += 1 + len;
    }
}

fn parse_response(msg: &[u8], name: &str, qtype: u16) -> Result<Vec<IpAddr>, DnsError> {
    let rcode = msg[3] & 0x0F;
    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;
    let mut pos = 12;
    for _ in 0..qdcount {
        pos = skip_name(msg, pos).ok_or_else(|| DnsError::Message("bad response".into()))?;
        pos += 4;
    }
    let mut out = Vec::new();
    for _ in 0..ancount {
        pos = skip_name(msg, pos).ok_or_else(|| DnsError::Message("bad response".into()))?;
        if pos + 10 > msg.len() {
            break;
        }
        let rtype = u16::from_be_bytes([msg[pos], msg[pos + 1]]);
        let rdlen = u16::from_be_bytes([msg[pos + 8], msg[pos + 9]]) as usize;
        pos += 10;
        if pos + rdlen > msg.len() {
            break;
        }
        let rdata = &msg[pos..pos + rdlen];
        match rtype {
            1 if rdlen == 4 => out.push(IpAddr::from([rdata[0], rdata[1], rdata[2], rdata[3]])),
            28 if rdlen == 16 => {
                let mut a = [0u8; 16];
                a.copy_from_slice(rdata);
                out.push(IpAddr::from(a));
            }
            _ => {}
        }
        pos += rdlen;
    }
    if rcode != 0 || out.is_empty() {
        return Err(DnsError::NoRecords {
            name: name.to_string(),
            qtype: if qtype == 28 { "AAAA" } else { "A" },
        });
    }
    Ok(out)
}

fn read_hosts() -> Vec<(String, IpAddr)> {
    let mut out = Vec::new();
    if let Ok(content) = std::fs::read_to_string("/etc/hosts") {
        for line in content.lines() {
            let line = line.split('#').next().unwrap_or("");
            let mut it = line.split_whitespace();
            if let Some(ip) = it.next() {
                if let Ok(ip) = ip.parse::<IpAddr>() {
                    for name in it {
                        out.push((name.to_ascii_lowercase(), ip));
                    }
                }
            }
        }
    }
    out
}

fn read_resolv_conf() -> Vec<SocketAddr> {
    let mut out = Vec::new();
    if let Ok(content) = std::fs::read_to_string("/etc/resolv.conf") {
        for line in content.lines() {
            let line = line.split('#').next().unwrap_or("").trim();
            let mut it = line.split_whitespace();
            if it.next() == Some("nameserver") {
                if let Some(ns) = it.next() {
                    if let Ok(ip) = ns.parse::<IpAddr>() {
                        out.push(SocketAddr::new(ip, 53));
                    }
                }
            }
        }
    }
    if out.is_empty() {
        out.push("127.0.0.1:53".parse().unwrap());
    }
    out
}
EOF
echo ok

