    Tls(TlsError),
    Http2(String),
    Other(String),
}

impl fmt::Display for ClientError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ClientError::Io(e) => write!(f, "{}", e),
            ClientError::Timeout => f.write_str("timeout"),
            ClientError::Deadline => f.write_str("aborted due to deadline"),
            ClientError::Parse(m) => f.write_str(m),
            ClientError::IncompleteMessage => f.write_str("connection closed before message completed"),
            ClientError::Canceled => f.write_str("operation was canceled"),
            ClientError::BodyRead => f.write_str("error reading a body from connection"),
            ClientError::RedirectLimit => f.write_str("Redirection limit has reached"),
            ClientError::UrlGen(e) => write!(f, "{}", e),
            ClientError::Dns(e) => write!(f, "{}", e),
            ClientError::Tls(e) => write!(f, "{}", e),
            ClientError::Http2(m) => f.write_str(m),
            ClientError::Other(m) => f.write_str(m),
        }
    }
}

impl std::error::Error for ClientError {}

impl From<UrlGeneratorError> for ClientError {
    fn from(e: UrlGeneratorError) -> Self {
        ClientError::UrlGen(e)
    }
}

impl From<DnsError> for ClientError {
    fn from(e: DnsError) -> Self {
        ClientError::Dns(e)
    }
}

/// Limits for the current request (request timeout + global deadline).
#[derive(Clone, Copy)]
pub struct Limits {
    pub request_deadline: Option<Instant>,
    pub global_deadline: Option<Instant>,
}

impl Limits {
    fn earliest(&self) -> Option<Instant> {
        match (self.request_deadline, self.global_deadline) {
            (Some(a), Some(b)) => Some(a.min(b)),
            (Some(a), None) => Some(a),
            (None, Some(b)) => Some(b),
            (None, None) => None,
        }
    }

    /// Returns the remaining time until the earliest limit, or an error when it has already passed.
    fn remaining(&self) -> Result<Option<Duration>, ClientError> {
        match self.earliest() {
            None => Ok(None),
            Some(limit) => {
                let now = Instant::now();
                if now >= limit {
                    Err(self.classify())
                } else {
                    Ok(Some(limit - now))
                }
            }
        }
    }

    fn classify(&self) -> ClientError {
        let now = Instant::now();
        if let Some(g) = self.global_deadline {
            if now >= g {
                return ClientError::Deadline;
            }
        }
        if let Some(r) = self.request_deadline {
            if now >= r {
                return ClientError::Timeout;
            }
        }
        // Timed out but neither limit passed? treat as timeout.
        ClientError::Timeout
    }

    fn map_io(&self, e: io::Error) -> ClientError {
        if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut {
            self.classify()
        } else {
            ClientError::Io(e)
        }
    }
}

pub enum Stream {
    Tcp(TcpStream),
    Tls { tcp: TcpStream, tls: TlsStream },
    Unix(UnixStream),
}

impl Stream {
    fn set_timeout(&self, d: Option<Duration>) -> io::Result<()> {
        match self {
            Stream::Tcp(s) | Stream::Tls { tcp: s, .. } => {
                s.set_read_timeout(d)?;
                s.set_write_timeout(d)
            }
            Stream::Unix(s) => {
                s.set_read_timeout(d)?;
                s.set_write_timeout(d)
            }
        }
    }

    fn raw_fd(&self) -> i32 {
        match self {
            Stream::Tcp(s) | Stream::Tls { tcp: s, .. } => s.as_raw_fd(),
            Stream::Unix(s) => s.as_raw_fd(),
        }
    }

    /// Returns true when the peer has closed the connection (EOF is pending).
    fn peer_closed(&self) -> bool {
        let fd = self.raw_fd();
        let mut b = [0u8; 1];
        let r = unsafe {
            libc::recv(
                fd,
                b.as_mut_ptr() as *mut libc::c_void,
                1,
                libc::MSG_PEEK | libc::MSG_DONTWAIT,
            )
        };
        if r == 0 {
            return true;
        }
        if r < 0 {
            let err = io::Error::last_os_error();
            return !(err.kind() == io::ErrorKind::WouldBlock || err.kind() == io::ErrorKind::Interrupted);
        }
        false
    }

    pub fn alpn_h2(&self) -> bool {
        match self {
            Stream::Tls { tls, .. } => tls.alpn.as_deref() == Some(b"h2"),
            _ => false,
        }
    }
}

impl Read for Stream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Stream::Tcp(s) => s.read(buf),
            Stream::Tls { tls, .. } => tls.read(buf),
            Stream::Unix(s) => s.read(buf),
        }
    }
}

impl Write for Stream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Stream::Tcp(s) => s.write(buf),
            Stream::Tls { tls, .. } => tls.write(buf),
            Stream::Unix(s) => s.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            Stream::Tcp(s) => s.flush(),
            Stream::Tls { tls, .. } => tls.flush(),
            Stream::Unix(s) => s.flush(),
        }
    }
}

/// A connection with a read buffer.
pub struct Connection {
    pub stream: Stream,
    buf: Vec<u8>,
    pos: usize,
    /// (scheme, host, port) the connection is for.
    pub key: (String, String, u16),
}

impl Connection {
    pub fn new(stream: Stream, key: (String, String, u16)) -> Self {
        Connection {
            stream,
            buf: Vec::with_capacity(16 * 1024),
            pos: 0,
            key,
        }
    }

    fn buffered(&self) -> &[u8] {
        &self.buf[self.pos..]
    }

    fn consume(&mut self, n: usize) {
        self.pos += n;
        if self.pos >= self.buf.len() {
            self.buf.clear();
            self.pos = 0;
        }
    }

    /// Read more data into the buffer. Returns the number of bytes read (0 = EOF).
    fn fill(&mut self, limits: &Limits) -> Result<usize, ClientError> {
        if self.pos > 0 && self.pos == self.buf.len() {
            self.buf.clear();
            self.pos = 0;
        }
        let remaining = limits.remaining()?;
        self.stream.set_timeout(remaining).map_err(ClientError::Io)?;
        let old_len = self.buf.len();
        self.buf.resize(old_len + 16 * 1024, 0);
        loop {
            match self.stream.read(&mut self.buf[old_len..]) {
                Ok(n) => {
                    self.buf.truncate(old_len + n);
                    return Ok(n);
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => {
                    self.buf.truncate(old_len);
                    return Err(limits.map_io(e));
                }
            }
        }
    }

    fn write_all(&mut self, data: &[u8], limits: &Limits) -> Result<(), ClientError> {
        let remaining = limits.remaining()?;
        self.stream.set_timeout(remaining).map_err(ClientError::Io)?;
        self.stream.write_all(data).map_err(|e| limits.map_io(e))
    }
}

