fn is_https(url: &Url) -> bool {
    url.scheme() == "https"
}

fn url_port(url: &Url) -> u16 {
    url.port_or_known_default().unwrap_or(if is_https(url) { 443 } else { 80 })
}

/// Path + query of a URL (origin form).
pub fn origin_form(url: &Url) -> String {
    let mut s = url.path().to_string();
    if let Some(q) = url.query() {
        s.push('?');
        s.push_str(q);
    }
    s
}

/// Absolute form of a URL without the fragment.
pub fn absolute_form(url: &Url) -> String {
    let mut u = url.clone();
    u.set_fragment(None);
    u.to_string()
}

pub fn host_header_value(url: &Url) -> String {
    url.authority().to_string()
}

impl Client {
    pub fn new(config: Arc<ClientConfig>) -> Self {
        Client {
            config,
            conn: None,
            rng: StdRng::from_entropy(),
            h2: None,
        }
    }

    fn resolve_addr(&mut self, host: &str, port: u16) -> Result<SocketAddr, ClientError> {
        let (target_host, target_port) = self.config.resolver.connect_target(host, port, &mut self.rng);
        let addrs = self.config.resolver.lookup(&target_host)?;
        let ip: IpAddr = if addrs.len() == 1 {
            addrs[0]
        } else {
            use rand::seq::SliceRandom;
            *addrs.choose(&mut self.rng).unwrap()
        };
        Ok(SocketAddr::new(ip, target_port))
    }

    fn tcp_connect(&self, addr: SocketAddr, limits: &Limits) -> Result<TcpStream, ClientError> {
        let mut timeout = self.config.connect_timeout;
        if let Some(rem) = limits.remaining()? {
            if rem < timeout {
                timeout = rem;
            }
        }
        match TcpStream::connect_timeout(&addr, timeout) {
            Ok(s) => {
                let _ = s.set_nodelay(true);
                Ok(s)
            }
            Err(e) => {
                if e.kind() == io::ErrorKind::TimedOut || e.kind() == io::ErrorKind::WouldBlock {
                    // Either the connect timeout or a request limit hit.
                    let now = Instant::now();
                    if let Some(g) = limits.global_deadline {
                        if now >= g {
                            return Err(ClientError::Deadline);
                        }
                    }
                    Err(ClientError::Timeout)
                } else {
                    Err(ClientError::Io(e))
                }
            }
        }
    }

    fn tls_wrap(&self, tcp: TcpStream, host: &str, limits: &Limits) -> Result<Stream, ClientError> {
        let ctx = self
            .config
            .tls
            .as_ref()
            .ok_or_else(|| ClientError::Other("TLS is not configured".to_string()))?;
        tcp.set_read_timeout(limits.remaining()?).map_err(ClientError::Io)?;
        tcp.set_write_timeout(limits.remaining()?).map_err(ClientError::Io)?;
        let sni = host.trim_start_matches('[').trim_end_matches(']');
        match ctx.connect(tcp.as_raw_fd(), sni, !self.config.insecure) {
            Ok(tls) => Ok(Stream::Tls { tcp, tls }),
            Err(TlsError::Io(e)) => Err(limits.map_io(e)),
            Err(e) => Err(ClientError::Tls(e)),
        }
    }

    /// Establish a connection for `url`. Returns the connection and the connection timing.
    fn connect(&mut self, url: &Url, start: Instant, limits: &Limits) -> Result<(Connection, ConnectionTime), ClientError> {
        let _ = start;
        let host = url.host_str().unwrap_or("").to_string();
        let port = url_port(url);
        let key = (url.scheme().to_string(), host.clone(), port);
        let https = is_https(url);

        if let (Some(path), false) = (&self.config.unix_socket, https) {
            let dns_lookup = Instant::now();
            limits.remaining()?;
            let s = UnixStream::connect(path).map_err(ClientError::Io)?;
            let dialup = Instant::now();
            return Ok((Connection::new(Stream::Unix(s), key), ConnectionTime { dns_lookup, dialup }));
        }

        if let Some(proxy) = self.config.proxy_url.clone() {
            let proxy_host = proxy.host_str().unwrap_or("").to_string();
            let proxy_port = url_port(&proxy);
            let addr = self.resolve_addr(&proxy_host, proxy_port)?;
            let dns_lookup = Instant::now();
            let tcp = self.tcp_connect(addr, limits)?;
            let mut stream = if is_https(&proxy) {
                self.tls_wrap(tcp, &proxy_host, limits)?
            } else {
                Stream::Tcp(tcp)
            };
            if https {
                // CONNECT tunnel
                let mut req = format!("CONNECT {}:{} HTTP/1.1\r\n", host, port);
                for (k, v) in &self.config.proxy_headers {
                    req.push_str(k);
                    req.push_str(": ");
                    req.push_str(v);
                    req.push_str("\r\n");
                }
                req.push_str("\r\n");
                let mut conn = Connection::new(stream, key.clone());
                conn.write_all(req.as_bytes(), limits)?;
                let resp = read_response(&mut conn, false, limits, &mut None)?;
                if !(200..300).contains(&resp.status) {
                    return Err(ClientError::Other(format!("proxy returned status {}", resp.status)));
                }
                // tunnel established; wrap with TLS
                let tcp = match conn.stream {
                    Stream::Tcp(t) => t,
                    _ => return Err(ClientError::Other("https proxy to https target is not supported".to_string())),
                };
                stream = self.tls_wrap(tcp, &host, limits)?;
            }
            let dialup = Instant::now();
            return Ok((Connection::new(stream, key), ConnectionTime { dns_lookup, dialup }));
        }

        let addr = self.resolve_addr(&host, port)?;
        let dns_lookup = Instant::now();
        let tcp = self.tcp_connect(addr, limits)?;
        let stream = if https {
            self.tls_wrap(tcp, &host, limits)?
        } else {
            Stream::Tcp(tcp)
        };
        let dialup = Instant::now();
        Ok((Connection::new(stream, key), ConnectionTime { dns_lookup, dialup }))
    }

    pub fn pick_body(&mut self) -> Option<Vec<u8>> {
        match &self.config.body {
            Body::Empty => None,
            Body::Static(b) => Some(b.as_ref().clone()),
            Body::Lines(lines) => {
                use rand::seq::SliceRandom;
                lines.choose(&mut self.rng).cloned()
            }
        }
    }

    /// Build the list of request headers for `url` (HTTP/1.x).
    pub fn build_headers(&self, url: &Url, via_proxy: bool, body: Option<&[u8]>) -> Vec<(String, String)> {
        let mut headers: Vec<(String, String)> = Vec::new();
        if let Some(aws) = &self.config.aws {
            let now = chrono::Utc::now();
            let signed = crate::aws::sign(aws, &self.config.method, url, body.unwrap_or(&[]), now);
            for (k, v) in signed.headers {
                headers.push((k, v));
            }
            for (k, v) in &self.config.headers {
                insert_header(&mut headers, k, v);
            }
            insert_header(&mut headers, "authorization", &signed.authorization);
            return headers;
        }
        for (k, v) in &self.config.headers {
            insert_header(&mut headers, k, v);
        }
        if via_proxy {
            for (k, v) in &self.config.proxy_headers {
                insert_header(&mut headers, k, v);
            }
        }
        if !headers.iter().any(|(k, _)| k == "host") {
            headers.push(("host".to_string(), host_header_value(url)));
        }
        headers
    }

    fn serialize_request(
        &self,
        method: &str,
        target: &str,
        version: HttpVersion,
        headers: &[(String, String)],
        body: Option<&[u8]>,
    ) -> Vec<u8> {
        let mut out = Vec::with_capacity(512);
        out.extend_from_slice(method.as_bytes());
        out.push(b' ');
        out.extend_from_slice(target.as_bytes());
        out.push(b' ');
        out.extend_from_slice(version.wire_name().as_bytes());
        out.extend_from_slice(b"\r\n");
        for (k, v) in headers {
            out.extend_from_slice(k.as_bytes());
            out.extend_from_slice(b": ");
            out.extend_from_slice(v.as_bytes());
            out.extend_from_slice(b"\r\n");
        }
        if let Some(body) = body {
            if !body.is_empty() && !headers.iter().any(|(k, _)| k == "content-length") {
                out.extend_from_slice(format!("content-length: {}\r\n", body.len()).as_bytes());
            }
        }
        out.extend_from_slice(b"\r\n");
        if let Some(body) = body {
            out.extend_from_slice(body);
        }
        out
    }

    /// Perform a single request/response exchange on a connection.
    fn exchange(
        &mut self,
        conn: &mut Connection,
        url: &Url,
        reused: bool,
        body: Option<&[u8]>,
        limits: &Limits,
        first_byte: &mut Option<Instant>,
    ) -> Result<Response, ClientError> {
        let via_proxy = self.config.proxy_url.is_some() && !is_https(url);
        let headers = self.build_headers(url, via_proxy, body);
        let target = if via_proxy { absolute_form(url) } else { origin_form(url) };
        let version = self.config.http_version;
        let req = self.serialize_request(&self.config.method, &target, version, &headers, body);
        if reused && conn.stream.peer_closed() {
            return Err(ClientError::Canceled);
        }
        conn.write_all(&req, limits)?;
        let is_head = self.config.method == "HEAD";
        read_response(conn, is_head, limits, first_byte)
    }

    /// Perform one logical request (following redirects) and return the measured result.
    pub fn work(&mut self, start_latency_correction: Option<Instant>) -> Result<RequestResult, ClientError> {
        let start = Instant::now();
        let limits = self.config.limits(start);
        if self.config.is_http2() {
            return self.work_http2(start, start_latency_correction, &limits);
        }
        if self.config.http_version == HttpVersion::Http09 {
            crate::debug::print_http09_panic();
            return Err(ClientError::Other("dispatch task is gone".to_string()));
        }
        let mut url = self.config.url_generator.generate(&mut self.rng)?;
        let body = self.pick_body();
        let mut connection_time: Option<ConnectionTime> = None;
        let mut first_byte: Option<Instant> = None;
        let mut redirects_left = self.config.redirect_limit;
        let mut redirected = false;
        // temporary connection used for redirects to other hosts
        let mut temp_conn: Option<Connection> = None;

        loop {
            let key = (
                url.scheme().to_string(),
                url.host_str().unwrap_or("").to_string(),
                url_port(&url),
            );
            // Choose the connection to use.
            let use_temp = temp_conn.as_ref().map(|c| c.key == key).unwrap_or(false);
            let (response, keep_alive) = if use_temp {
                let mut conn = temp_conn.take().unwrap();
                let r = self.exchange(&mut conn, &url, true, body.as_deref(), &limits, &mut first_byte);
                let r = r?;
                let ka = r.keep_alive;
                if ka {
                    temp_conn = Some(conn);
                }
                (r, ka)
            } else if self.conn.as_ref().map(|c| c.key == key).unwrap_or(false) && !self.config.disable_keepalive {
                let mut conn = self.conn.take().unwrap();
                match self.exchange(&mut conn, &url, true, body.as_deref(), &limits, &mut first_byte) {
                    Ok(r) => {
                        let ka = r.keep_alive;
                        if ka {
                            self.conn = Some(conn);
                        }
                        (r, ka)
                    }
                    Err(e) => {
                        return Err(e);
                    }
                }
            } else {
                let (mut conn, ct) = self.connect(&url, start, &limits)?;
                if connection_time.is_none() {
                    connection_time = Some(ct);
                }
                let r = self.exchange(&mut conn, &url, false, body.as_deref(), &limits, &mut first_byte)?;
                let ka = r.keep_alive && !self.config.disable_keepalive;
                if ka {
                    if redirected || self.conn.is_some() {
                        temp_conn = Some(conn);
                    } else {
                        self.conn = Some(conn);
                    }
                }
                (r, ka)
            };
            let _ = keep_alive;

            // Redirect handling
            if (300..400).contains(&response.status) {
                if let Some(location) = response.header("location") {
                    if self.config.redirect_limit > 0 {
                        if redirects_left == 0 {
                            return Err(ClientError::RedirectLimit);
                        }
                        redirects_left -= 1;
                        let new_url = url
                            .join(location)
                            .map_err(|e| ClientError::Other(e.to_string()))?;
                        url = new_url;
                        redirected = true;
                        first_byte = None;
                        continue;
                    }
                }
            }
            if redirected {
                first_byte = None;
            }
            let end = Instant::now();
            return Ok(RequestResult {
                start_latency_correction,
                start,
                connection_time,
                first_byte,
                end,
                status: response.status,
                len_bytes: response.body.len(),
                url_path: origin_form(&url),
            });
        }
    }

    /// Perform a single request and return the raw request/response for `--debug`.
    pub fn debug_request(&mut self) -> Result<(Url, Vec<(String, String)>, Option<Vec<u8>>, Response), ClientError> {
        let start = Instant::now();
        let limits = Limits {
            request_deadline: None,
            global_deadline: None,
        };
        let url = self.config.url_generator.generate(&mut self.rng)?;
        let body = self.pick_body();
        let via_proxy = self.config.proxy_url.is_some() && !is_https(&url);
        let headers = self.build_headers(&url, via_proxy, body.as_deref());
        if self.config.is_http2() {
            let resp = self.debug_http2(&url, &headers, body.as_deref(), &limits)?;
            return Ok((url, headers, body, resp));
        }
        if self.config.http_version == HttpVersion::Http09 {
            crate::debug::print_http09_panic();
            return Err(ClientError::Other("dispatch task is gone".to_string()));
        }
        let (mut conn, _ct) = self.connect(&url, start, &limits)?;
        let target = if via_proxy { absolute_form(&url) } else { origin_form(&url) };
        let req = self.serialize_request(&self.config.method, &target, self.config.http_version, &headers, body.as_deref());
        conn.write_all(&req, &limits)?;
        let is_head = self.config.method == "HEAD";
        let mut fb = None;
        let resp = read_response(&mut conn, is_head, &limits, &mut fb)?;
        Ok((url, headers, body, resp))
    }

    pub fn connect_for_url(&mut self, url: &Url, limits: &Limits) -> Result<(Connection, ConnectionTime), ClientError> {
        let start = Instant::now();
        self.connect(url, start, limits)
    }
}

fn insert_header(headers: &mut Vec<(String, String)>, k: &str, v: &str) {
    if let Some(e) = headers.iter_mut().find(|(n, _)| n == k) {
        e.1 = v.to_string();
    } else {
        headers.push((k.to_string(), v.to_string()));
    }
}

fn find_header_end(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n").map(|p| p + 4)
}

fn is_token(b: &[u8]) -> bool {
    !b.is_empty()
        && b.iter().all(|&c| {
            matches!(c, b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~' | b'0'..=b'9' | b'a'..=b'z' | b'A'..=b'Z')
        })
}

fn parse_head(head: &[u8]) -> Result<(HttpVersion, u16, Vec<(String, String)>), ClientError> {
    let text = head;
    let mut lines = text.split(|&b| b == b'\n').map(|l| l.strip_suffix(b"\r").unwrap_or(l));
    let status_line = lines.next().ok_or(ClientError::IncompleteMessage)?;
    let mut parts = status_line.splitn(3, |&b| b == b' ');
    let version = parts.next().unwrap_or(b"");
    let version = match version {
        b"HTTP/1.1" => HttpVersion::Http11,
        b"HTTP/1.0" => HttpVersion::Http10,
        _ => return Err(ClientError::Parse("invalid HTTP version parsed")),
    };
    let status = parts.next().ok_or(ClientError::Parse("invalid HTTP status-code parsed"))?;
    if status.len() != 3 || !status.iter().all(|c| c.is_ascii_digit()) {
        return Err(ClientError::Parse("invalid HTTP status-code parsed"));
    }
    let status: u16 = std::str::from_utf8(status).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    for line in lines {
        if line.is_empty() {
            break;
        }
        let colon = line
            .iter()
            .position(|&b| b == b':')
            .ok_or(ClientError::Parse("invalid HTTP header parsed"))?;
        let name = &line[..colon];
        if !is_token(name) {
            return Err(ClientError::Parse("invalid HTTP header parsed"));
        }
        let value = &line[colon + 1..];
        let value = trim_ws(value);
        if !value.iter().all(|&b| b == b'\t' || (b >= 0x20 && b != 0x7f)) {
            return Err(ClientError::Parse("invalid HTTP header parsed"));
        }
        headers.push((
            String::from_utf8_lossy(name).to_ascii_lowercase(),
            String::from_utf8_lossy(value).into_owned(),
        ));
    }
    Ok((version, status, headers))
}

fn trim_ws(b: &[u8]) -> &[u8] {
    let mut start = 0;
    let mut end = b.len();
    while start < end && (b[start] == b' ' || b[start] == b'\t') {
        start += 1;
    }
    while end > start && (b[end - 1] == b' ' || b[end - 1] == b'\t') {
        end -= 1;
    }
    &b[start..end]
}

enum BodyKind {
    None,
    Length(usize),
    Chunked,
    Close,
}

/// Read a complete HTTP/1.x response from the connection.
pub fn read_response(
    conn: &mut Connection,
    is_head: bool,
    limits: &Limits,
    first_byte: &mut Option<Instant>,
) -> Result<Response, ClientError> {
    // Read head
    let head_end = loop {
        if let Some(p) = find_header_end(conn.buffered()) {
            break p;
        }
        if conn.buffered().len() > 400 * 1024 {
            return Err(ClientError::Parse("message head is too large"));
        }
        let n = conn.fill(limits)?;
        if n == 0 {
            return Err(ClientError::IncompleteMessage);
        }
    };
    let (version, status, headers) = parse_head(&conn.buffered()[..head_end])?;
    conn.consume(head_end);

    // Determine body kind
    let mut content_length: Option<usize> = None;
    let mut chunked = false;
    let mut conn_close = false;
    let mut conn_keep_alive = false;
    for (name, value) in &headers {
        match name.as_str() {
            "content-length" => {
                let v: usize = value
                    .trim()
                    .parse()
                    .map_err(|_| ClientError::Parse("invalid content-length parsed"))?;
                if let Some(prev) = content_length {
                    if prev != v {
                        return Err(ClientError::Parse("invalid content-length parsed"));
                    }
                }
                content_length = Some(v);
            }
            "transfer-encoding" => {
                if value
                    .split(',')
                    .any(|t| t.trim().eq_ignore_ascii_case("chunked"))
                {
                    chunked = true;
                }
            }
            "connection" => {
                for t in value.split(',') {
                    let t = t.trim();
                    if t.eq_ignore_ascii_case("close") {
                        conn_close = true;
                    } else if t.eq_ignore_ascii_case("keep-alive") {
                        conn_keep_alive = true;
                    }
                }
            }
            _ => {}
        }
    }
    let kind = if is_head || (100..200).contains(&status) || status == 204 || status == 304 {
        BodyKind::None
    } else if chunked {
        BodyKind::Chunked
    } else if let Some(len) = content_length {
        BodyKind::Length(len)
    } else {
        BodyKind::Close
    };
    let mut keep_alive = match version {
        HttpVersion::Http10 => conn_keep_alive && !conn_close,
        _ => !conn_close,
    };

    let mut body = Vec::new();
    match kind {
        BodyKind::None => {}
        BodyKind::Length(len) => {
            if len > 0 && !conn.buffered().is_empty() && first_byte.is_none() {
                *first_byte = Some(Instant::now());
            }
            while body.len() < len {
                let avail = conn.buffered();
                if !avail.is_empty() {
                    let take = avail.len().min(len - body.len());
                    body.extend_from_slice(&avail[..take]);
                    conn.consume(take);
                    continue;
                }
                let n = conn.fill(limits)?;
                if n == 0 {
                    return Err(ClientError::BodyRead);
                }
                if first_byte.is_none() {
                    *first_byte = Some(Instant::now());
                }
            }
        }
        BodyKind::Chunked => {
            loop {
                // read chunk size line
                let line_end = loop {
                    if let Some(p) = conn.buffered().windows(2).position(|w| w == b"\r\n") {
                        break p;
                    }
                    let n = conn.fill(limits)?;
                    if n == 0 {
                        return Err(ClientError::BodyRead);
                    }
                };
                let line = conn.buffered()[..line_end].to_vec();
                conn.consume(line_end + 2);
                let size_str = line.split(|&b| b == b';').next().unwrap_or(&[]);
                let size_str = std::str::from_utf8(trim_ws(size_str)).map_err(|_| ClientError::BodyRead)?;
                let size = usize::from_str_radix(size_str, 16).map_err(|_| ClientError::BodyRead)?;
                if size == 0 {
                    // trailers until empty line
                    loop {
                        let line_end = loop {
                            if let Some(p) = conn.buffered().windows(2).position(|w| w == b"\r\n") {
                                break p;
                            }
                            let n = conn.fill(limits)?;
                            if n == 0 {
                                return Err(ClientError::BodyRead);
                            }
                        };
                        let empty = line_end == 0;
                        conn.consume(line_end + 2);
                        if empty {
                            break;
                        }
                    }
                    break;
                }
                if first_byte.is_none() {
                    *first_byte = Some(Instant::now());
                }
                let mut remaining = size + 2; // include CRLF
                while remaining > 0 {
                    let avail = conn.buffered();
                    if !avail.is_empty() {
                        let take = avail.len().min(remaining);
                        let data_part = take.min(remaining.saturating_sub(2));
                        if remaining > 2 {
                            body.extend_from_slice(&avail[..data_part]);
                        }
                        conn.consume(take);
                        remaining -= take;
                        continue;
                    }
                    let n = conn.fill(limits)?;
                    if n == 0 {
                        return Err(ClientError::BodyRead);
                    }
                }
            }
        }
        BodyKind::Close => {
            keep_alive = false;
            if !conn.buffered().is_empty() && first_byte.is_none() {
                *first_byte = Some(Instant::now());
            }
            loop {
                let avail = conn.buffered();
                if !avail.is_empty() {
                    body.extend_from_slice(avail);
                    let n = avail.len();
                    conn.consume(n);
                }
                let n = conn.fill(limits)?;
                if n == 0 {
                    break;
                }
                if first_byte.is_none() {
                    *first_byte = Some(Instant::now());
                }
            }
        }
    }
    Ok(Response {
        version,
        status,
        headers,
        body,
        keep_alive,
    })
}
EOF
echo ok"}

