        self.end
            .saturating_duration_since(self.start_latency_correction.unwrap_or(self.start))
    }
}

#[derive(Clone)]
pub enum Body {
    Empty,
    Static(Arc<Vec<u8>>),
    Lines(Arc<Vec<Vec<u8>>>),
}

pub struct AwsConfig {
    pub access_key: String,
    pub secret_key: String,
    pub session_token: Option<String>,
