use crate::client::RequestResult;
use crate::result_data::*;
use std::io::Write;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TimeUnit {
    Nano,
    Micro,
    Milli,
    Sec,
    Min,
    Hour,
}

impl TimeUnit {
    pub fn from_arg(s: &str) -> Option<Self> {
        match s {
            "ns" => Some(TimeUnit::Nano),
            "us" => Some(TimeUnit::Micro),
            "ms" => Some(TimeUnit::Milli),
            "s" => Some(TimeUnit::Sec),
            "m" => Some(TimeUnit::Min),
            "h" => Some(TimeUnit::Hour),
            _ => None,
        }
    }

    pub fn from_secs(secs: f64) -> Self {
        if secs >= 3600.0 {
            TimeUnit::Hour
        } else if secs >= 60.0 {
            TimeUnit::Min
        } else if secs >= 1.0 {
            TimeUnit::Sec
        } else if secs >= 0.001 {
            TimeUnit::Milli
        } else if secs >= 0.000001 {
            TimeUnit::Micro
        } else {
            TimeUnit::Nano
        }
    }

    pub fn name(&self) -> &'static str {
        match self {
            TimeUnit::Nano => "ns",
            TimeUnit::Micro => "us",
            TimeUnit::Milli => "ms",
            TimeUnit::Sec => "sec",
            TimeUnit::Min => "min",
            TimeUnit::Hour => "hr",
        }
    }

    pub fn scale(&self) -> f64 {
        match self {
            TimeUnit::Nano => 1e9,
            TimeUnit::Micro => 1e6,
            TimeUnit::Milli => 1e3,
            TimeUnit::Sec => 1.0,
            TimeUnit::Min => 1.0 / 60.0,
            TimeUnit::Hour => 1.0 / 3600.0,
        }
    }

    pub fn convert(&self, secs: f64) -> f64 {
        secs * self.scale()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutputFormat {
    Text,
    Json,
    Csv,
    Quiet,
}

pub fn format_bytes(bytes: f64) -> String {
    const UNITS: [&str; 6] = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    if bytes < 1024.0 {
        return format!("{} B", bytes as u64);
    }
    let mut v = bytes / 1024.0;
    let mut i = 0;
    while v >= 1024.0 && i < UNITS.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    format!("{:.2} {}", v, UNITS[i])
}

pub struct Summary<'a> {
    pub res: &'a ResultData,
    pub start: Instant,
    pub total_duration: Duration,
}

fn details(res: &ResultData) -> (Vec<f64>, Vec<f64>) {
    let mut dialup = Vec::new();
    let mut dns = Vec::new();
    for r in &res.success {
        if let Some(ct) = &r.connection_time {
            dialup.push(ct.dialup.saturating_duration_since(r.start).as_secs_f64());
            dns.push(ct.dns_lookup.saturating_duration_since(r.start).as_secs_f64());
        }
    }
    (dialup, dns)
}

fn print_histogram<W: Write>(w: &mut W, values: &[f64], unit: TimeUnit) -> std::io::Result<()> {
    let hist = histogram(values, 10);
    let max_count = hist.iter().map(|(_, c)| *c).max().unwrap_or(0);
    let count_width = hist.iter().map(|(_, c)| c.to_string().len()).max().unwrap_or(1);
    let max_label = hist.iter().map(|(l, _)| unit.convert(*l)).fold(f64::NAN, f64::max);
    let label_width = (max_label.log10().floor() as usize).saturating_add(5);
    for (label, count) in &hist {
        let bar_len = if max_count == 0 {
            0
        } else {
            (count * 32) / max_count
        };
        let bar: String = "■".repeat(bar_len);
        writeln!(
            w,
            "  {:>lw$.3} {} [{}]{} |{}",
            unit.convert(*label),
            unit.name(),
            count,
            " ".repeat(count_width - count.to_string().len()),
            bar,
            lw = label_width
        )?;
    }
    Ok(())
}

fn print_distribution<W: Write>(w: &mut W, sorted: &[f64], unit: TimeUnit) -> std::io::Result<()> {
    for (_, p) in PERCENTILES.iter() {
        writeln!(
            w,
            "  {:.2}% in {:.4} {}",
            p,
            unit.convert(percentile(sorted, *p)),
            unit.name()
        )?;
    }
    Ok(())
}

pub fn print_text<W: Write>(
    w: &mut W,
    res: &ResultData,
    total_duration: Duration,
    time_unit: Option<TimeUnit>,
    stats_success_breakdown: bool,
    disable_color: bool,
) -> std::io::Result<()> {
    let _ = disable_color;
    let durations = res.durations();
    let total = total_duration.as_secs_f64();
    let slowest = fmax(durations.iter().copied());
    let fastest = fmin(durations.iter().copied());
    let average = fmean(&durations);
    let unit = time_unit.unwrap_or_else(|| TimeUnit::from_secs(slowest));
    let total_requests = res.total_requests();
    let success_rate = res.success.len() as f64 / total_requests as f64 * 100.0;
    let rps = total_requests as f64 / total;
    let total_bytes = res.total_bytes();

    writeln!(w, "Summary:")?;
    writeln!(w, "  Success rate:\t{:.2}%", success_rate)?;
    writeln!(w, "  Total:\t{:.4} {}", unit.convert(total), unit.name())?;
    writeln!(w, "  Slowest:\t{:.4} {}", unit.convert(slowest), unit.name())?;
    writeln!(w, "  Fastest:\t{:.4} {}", unit.convert(fastest), unit.name())?;
    writeln!(w, "  Average:\t{:.4} {}", unit.convert(average), unit.name())?;
    writeln!(w, "  Requests/sec:\t{:.4}", rps)?;
    writeln!(w)?;
    writeln!(w, "  Total data:\t{}", format_bytes(total_bytes as f64))?;
    if res.success.is_empty() {
        writeln!(w, "  Size/request:\tNaN")?;
    } else {
        writeln!(
            w,
            "  Size/request:\t{}",
            format_bytes((total_bytes / res.success.len()) as f64)
        )?;
    }
    writeln!(w, "  Size/sec:\t{}", format_bytes(total_bytes as f64 / total))?;
    writeln!(w)?;
    writeln!(w, "Response time histogram:")?;
    print_histogram(w, &durations, unit)?;
    writeln!(w)?;
    writeln!(w, "Response time distribution:")?;
    let mut sorted = durations.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    print_distribution(w, &sorted, unit)?;
    writeln!(w)?;

    if stats_success_breakdown {
        let (succ, not_succ): (Vec<&RequestResult>, Vec<&RequestResult>) =
            res.success.iter().partition(|r| (200..300).contains(&r.status));
        let succ_d: Vec<f64> = succ.iter().map(|r| r.duration().as_secs_f64()).collect();
        let mut not_succ_d: Vec<f64> = not_succ
            .iter()
