        print_distribution(w, &s, unit)?;
        writeln!(w)?;
        writeln!(w, "Response time histogram (4xx + 5xx only):")?;
        print_histogram(w, &not_succ_d, unit)?;
        writeln!(w)?;
        writeln!(w, "Response time distribution (4xx + 5xx only):")?;
        not_succ_d.sort_by(|a, b| a.partial_cmp(b).unwrap());
        print_distribution(w, &not_succ_d, unit)?;
        writeln!(w)?;
    }

    writeln!(w)?;
    writeln!(w, "Details (average, fastest, slowest):")?;
    let (dialup, dns) = details(res);
    writeln!(
        w,
        "  DNS+dialup:\t{:.4} {}, {:.4} {}, {:.4} {}",
        unit.convert(fmean(&dialup)),
        unit.name(),
        unit.convert(fmin(dialup.iter().copied())),
        unit.name(),
        unit.convert(fmax(dialup.iter().copied())),
