        writeln!(w, "Error distribution:")?;
        for (msg, count) in errors {
            writeln!(w, "  [{}] {}", count, msg)?;
        }
    }
    Ok(())
}

fn json_f64(v: f64) -> serde_json::Value {
    serde_json::Number::from_f64(v)
        .map(serde_json::Value::Number)
        .unwrap_or(serde_json::Value::Null)
}

fn json_histogram(values: &[f64]) -> serde_json::Value {
    let hist = histogram(values, 10);
    let mut map: std::collections::BTreeMap<String, usize> = Default::default();
    for (label, count) in hist {
        map.insert(format!("{}", label), count);
    }
    // Preserve numeric order (strings sort the same way for typical values).
    let mut entries: Vec<(String, usize)> = map.into_iter().collect();
    entries.sort_by(|a, b| {
        let fa: f64 = a.0.parse().unwrap_or(f64::NAN);
        let fb: f64 = b.0.parse().unwrap_or(f64::NAN);
        fa.partial_cmp(&fb).unwrap_or(std::cmp::Ordering::Equal)
    });
    let mut out = serde_json::Map::new();
    for (k, v) in entries {
        out.insert(k, serde_json::Value::from(v));
    }
    serde_json::Value::Object(out)
}

fn json_percentiles(sorted: &[f64]) -> serde_json::Value {
    let mut out = serde_json::Map::new();
    for (name, p) in PERCENTILES.iter() {
        out.insert(format!("p{}", name), json_f64(percentile(sorted, *p)));
    }
    serde_json::Value::Object(out)
}

fn json_stats(values: &[f64]) -> serde_json::Value {
    let mut out = serde_json::Map::new();
    out.insert("average".into(), json_f64(fmean(values)));
    out.insert("fastest".into(), json_f64(fmin(values.iter().copied())));
    out.insert("slowest".into(), json_f64(fmax(values.iter().copied())));
    serde_json::Value::Object(out)
}

pub fn print_json<W: Write>(
    w: &mut W,
    res: &ResultData,
    start: Instant,
    total_duration: Duration,
    stats_success_breakdown: bool,
) -> std::io::Result<()> {
    let durations = res.durations();
    let total = total_duration.as_secs_f64();
    let slowest = fmax(durations.iter().copied());
    let fastest = fmin(durations.iter().copied());
    let average = fmean(&durations);
    let total_requests = res.total_requests();
    let total_bytes = res.total_bytes();

    let mut summary = serde_json::Map::new();
    summary.insert(
        "successRate".into(),
        json_f64(res.success.len() as f64 / total_requests as f64),
    );
    summary.insert("total".into(), json_f64(total));
    summary.insert("slowest".into(), json_f64(slowest));
    summary.insert("fastest".into(), json_f64(fastest));
    summary.insert("average".into(), json_f64(average));
    summary.insert("requestsPerSec".into(), json_f64(total_requests as f64 / total));
    summary.insert("totalData".into(), serde_json::Value::from(total_bytes));
    summary.insert(
        "sizePerRequest".into(),
        if res.success.is_empty() {
            serde_json::Value::Null
        } else {
            serde_json::Value::from(total_bytes / res.success.len())
        },
    );
    summary.insert("sizePerSec".into(), json_f64(total_bytes as f64 / total));

    let mut root = serde_json::Map::new();
    root.insert("summary".into(), serde_json::Value::Object(summary));
    root.insert("responseTimeHistogram".into(), json_histogram(&durations));
    let mut sorted = durations.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    root.insert("latencyPercentiles".into(), json_percentiles(&sorted));

    if stats_success_breakdown {
        let succ: Vec<f64> = res
            .success
            .iter()
            .filter(|r| (200..300).contains(&r.status))
            .map(|r| r.duration().as_secs_f64())
            .collect();
        let not_succ: Vec<f64> = res
            .success
            .iter()
            .filter(|r| (400..600).contains(&r.status))
            .map(|r| r.duration().as_secs_f64())
            .collect();
        let mut s = succ.clone();
        s.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let mut ns = not_succ.clone();
        ns.sort_by(|a, b| a.partial_cmp(b).unwrap());
        root.insert("responseTimeHistogramSuccessful".into(), json_histogram(&succ));
        root.insert("latencyPercentilesSuccessful".into(), json_percentiles(&s));
        root.insert("responseTimeHistogramNotSuccessful".into(), json_histogram(&not_succ));
        root.insert("latencyPercentilesNotSuccessful".into(), json_percentiles(&ns));
    }

    let rps = rps_series(&res.success, start);
    let mut rps_sorted = rps.clone();
    rps_sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let mut rps_obj = serde_json::Map::new();
    rps_obj.insert("mean".into(), json_f64(fmean(&rps)));
    rps_obj.insert("stddev".into(), json_f64(fstddev(&rps)));
    rps_obj.insert("max".into(), json_f64(fmax(rps.iter().copied())));
    rps_obj.insert("min".into(), json_f64(fmin(rps.iter().copied())));
    rps_obj.insert("percentiles".into(), json_percentiles(&rps_sorted));
    root.insert("rps".into(), serde_json::Value::Object(rps_obj));

    let (dialup, dns) = details(res);
    let mut det = serde_json::Map::new();
    det.insert("DNSDialup".into(), json_stats(&dialup));
    det.insert("DNSLookup".into(), json_stats(&dns));
    root.insert("details".into(), serde_json::Value::Object(det));

    let mut codes = serde_json::Map::new();
    let mut code_list = res.status_code_distribution();
    code_list.sort_by_key(|(c, _)| *c);
    for (code, count) in code_list {
        codes.insert(code.to_string(), serde_json::Value::from(count));
    }
    root.insert("statusCodeDistribution".into(), serde_json::Value::Object(codes));

    let mut errs = serde_json::Map::new();
    for (msg, count) in &res.error_distribution {
        errs.insert(msg.clone(), serde_json::Value::from(*count));
    }
    root.insert("errorDistribution".into(), serde_json::Value::Object(errs));

    let s = serde_json::to_string_pretty(&serde_json::Value::Object(root)).unwrap();
    w.write_all(s.as_bytes())?;
    Ok(())
}

pub fn print_csv<W: Write>(w: &mut W, res: &ResultData, start: Instant) -> std::io::Result<()> {
    writeln!(
        w,
        "request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status"
    )?;
    for r in &res.success {
        let request_start = r.start.saturating_duration_since(start).as_secs_f64();
        let (dns, dialup) = match &r.connection_time {
            Some(ct) => (
                ct.dns_lookup.saturating_duration_since(r.start).as_secs_f64(),
                ct.dialup.saturating_duration_since(r.start).as_secs_f64(),
            ),
            None => (0.0, 0.0),
        };
        let response_delay = r
            .first_byte
            .map(|fb| fb.saturating_duration_since(r.start).as_secs_f64())
            .unwrap_or(0.0);
        writeln!(
            w,
            "{},{},{},{},{},{},{}",
            request_start,
            dns,
            dialup,
            response_delay,
            r.duration().as_secs_f64(),
            r.len_bytes,
            r.status
        )?;
    }
    Ok(())
}
