use crate::client::RequestResult;
use std::collections::BTreeMap;
use std::time::Duration;

#[derive(Default)]
pub struct ResultData {
    pub success: Vec<RequestResult>,
    pub error_distribution: BTreeMap<String, usize>,
}

impl ResultData {
    pub fn push(&mut self, r: Result<RequestResult, String>) {
        match r {
            Ok(r) => self.success.push(r),
            Err(e) => *self.error_distribution.entry(e).or_insert(0) += 1,
        }
    }

    pub fn len_errors(&self) -> usize {
        self.error_distribution.values().sum()
    }

    pub fn total_requests(&self) -> usize {
        self.success.len() + self.len_errors()
    }

    pub fn durations(&self) -> Vec<f64> {
        self.success.iter().map(|r| r.duration().as_secs_f64()).collect()
    }

    pub fn total_bytes(&self) -> usize {
        self.success.iter().map(|r| r.len_bytes).sum()
    }

    pub fn status_code_distribution(&self) -> Vec<(u16, usize)> {
        let mut map: BTreeMap<u16, usize> = BTreeMap::new();
        for r in &self.success {
            *map.entry(r.status).or_insert(0) += 1;
        }
        let mut v: Vec<(u16, usize)> = map.into_iter().collect();
        v.sort_by(|a, b| b.1.cmp(&a.1));
        v
    }

    pub fn error_distribution_sorted(&self) -> Vec<(String, usize)> {
        let mut v: Vec<(String, usize)> = self
            .error_distribution
            .iter()
            .map(|(k, v)| (k.clone(), *v))
            .collect();
        v.sort_by(|a, b| b.1.cmp(&a.1));
        v
    }
}

pub fn fmin(values: impl Iterator<Item = f64>) -> f64 {
    values.fold(f64::INFINITY, f64::min)
}

pub fn fmax(values: impl Iterator<Item = f64>) -> f64 {
    values.fold(f64::NEG_INFINITY, f64::max)
}

pub fn fmean(values: &[f64]) -> f64 {
    values.iter().sum::<f64>() / values.len() as f64
}

/// Sample standard deviation.
pub fn fstddev(values: &[f64]) -> f64 {
    let mean = fmean(values);
    let var = values.iter().map(|v| (v - mean) * (v - mean)).sum::<f64>() / (values.len() as f64 - 1.0);
    var.sqrt()
}

pub fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() {
        return f64::NAN;
    }
    let idx = (sorted.len() as f64 * p / 100.0) as usize;
    sorted.get(idx).copied().unwrap_or(*sorted.last().unwrap())
}

pub const PERCENTILES: [(&str, f64); 9] = [
    ("10", 10.0),
    ("25", 25.0),
    ("50", 50.0),
    ("75", 75.0),
    ("90", 90.0),
    ("95", 95.0),
    ("99", 99.0),
    ("99.9", 99.9),
    ("99.99", 99.99),
];

/// Histogram with `bins + 1` buckets whose labels are `min + step * i`.
pub fn histogram(values: &[f64], bins: usize) -> Vec<(f64, usize)> {
    let min = values.iter().copied().fold(f64::NAN, f64::min);
    let max = values.iter().copied().fold(f64::NAN, f64::max);
    let step = (max - min) / bins as f64;
    let mut ret: Vec<(f64, usize)> = (0..=bins).map(|i| (min + step * i as f64, 0usize)).collect();
    for &v in values {
        let f = ((v - min) / step).ceil();
        let mut idx = if f.is_nan() || f < 0.0 { 0 } else { f as usize };
        if idx > bins {
            idx = bins;
        }
        ret[idx].1 += 1;
    }
    ret
}

/// Requests per second computed from consecutive completion times.
pub fn rps_series(results: &[RequestResult], start: std::time::Instant) -> Vec<f64> {
    let mut ends: Vec<std::time::Instant> = results.iter().map(|r| r.end).collect();
    ends.sort();
    let mut out = Vec::with_capacity(ends.len());
    let mut prev = start;
    for end in ends {
        let d = end.saturating_duration_since(prev).as_secs_f64();
        out.push(1.0 / d);
        prev = end;
    }
    out
}

pub fn duration_secs(d: Duration) -> f64 {
    d.as_secs_f64()
}
