    Sec,
    Min,
    Hour,
}

impl TimeUnit {
    pub fn from_arg(s: &str) -> Option<Self> {
        match s {
            "ns" => Some(TimeUnit::Nano),
            "us" => Some(TimeUnit::Micro),
            "ms" => Some(TimeUnit::Milli),
            "s" => Some(TimeUnit::Sec),
            "m" => Some(TimeUnit::Min),
            "h" => Some(TimeUnit::Hour),
            _ => None,
        }
    }

    pub fn from_secs(secs: f64) -> Self {
        if secs >= 3600.0 {
            TimeUnit::Hour
        } else if secs >= 60.0 {
            TimeUnit::Min
        } else if secs >= 1.0 {
            TimeUnit::Sec
        } else if secs >= 0.001 {
            TimeUnit::Milli
        } else if secs >= 0.000001 {
            TimeUnit::Micro
        } else {
            TimeUnit::Nano
        }
    }

    pub fn name(&self) -> &'static str {
        match self {
            TimeUnit::Nano => "ns",
            TimeUnit::Micro => "us",
            TimeUnit::Milli => "ms",
            TimeUnit::Sec => "sec",
            TimeUnit::Min => "min",
            TimeUnit::Hour => "hr",
        }
    }

    pub fn scale(&self) -> f64 {
        match self {
            TimeUnit::Nano => 1e9,
            TimeUnit::Micro => 1e6,
            TimeUnit::Milli => 1e3,
            TimeUnit::Sec => 1.0,
            TimeUnit::Min => 1.0 / 60.0,
            TimeUnit::Hour => 1.0 / 3600.0,
        }
    }

    pub fn convert(&self, secs: f64) -> f64 {
        secs * self.scale()
    }
}

