//! Store results into a sqlite database via the system sqlite3 library.
#![allow(non_camel_case_types)]
use crate::client::RequestResult;
use std::ffi::{c_char, c_int, c_void, CStr, CString};
use std::ptr;
use std::time::Instant;

type sqlite3 = c_void;
type sqlite3_stmt = c_void;

const SQLITE_OK: c_int = 0;
const SQLITE_DONE: c_int = 101;

#[link(name = "sqlite3")]
extern "C" {
    fn sqlite3_open(filename: *const c_char, db: *mut *mut sqlite3) -> c_int;
    fn sqlite3_close(db: *mut sqlite3) -> c_int;
    fn sqlite3_exec(
        db: *mut sqlite3,
        sql: *const c_char,
        cb: *const c_void,
        arg: *mut c_void,
        errmsg: *mut *mut c_char,
    ) -> c_int;
    fn sqlite3_errmsg(db: *mut sqlite3) -> *const c_char;
    fn sqlite3_prepare_v2(
        db: *mut sqlite3,
        sql: *const c_char,
        n: c_int,
        stmt: *mut *mut sqlite3_stmt,
        tail: *mut *const c_char,
    ) -> c_int;
    fn sqlite3_bind_text(stmt: *mut sqlite3_stmt, idx: c_int, v: *const c_char, n: c_int, destructor: *const c_void) -> c_int;
    fn sqlite3_bind_double(stmt: *mut sqlite3_stmt, idx: c_int, v: f64) -> c_int;
    fn sqlite3_bind_int64(stmt: *mut sqlite3_stmt, idx: c_int, v: i64) -> c_int;
    fn sqlite3_bind_null(stmt: *mut sqlite3_stmt, idx: c_int) -> c_int;
    fn sqlite3_step(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_reset(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_finalize(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_free(p: *mut c_void);
}

const SQLITE_TRANSIENT: *const c_void = -1isize as *const c_void;

const CREATE_TABLE: &str = "CREATE TABLE IF NOT EXISTS oha (
            url TEXT NOT NULL,
            start REAL NOT NULL,
            start_latency_correction REAL,
            end REAL NOT NULL,
            duration REAL NOT NULL,
            status INTEGER NOT NULL,
            len_bytes INTEGER NOT NULL,
            run INTEGER NOT NULL
        )";

unsafe fn errmsg(db: *mut sqlite3) -> String {
    if db.is_null() {
        return "out of memory".to_string();
    }
    CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy().into_owned()
}

pub fn store(path: &str, start: Instant, results: &[RequestResult]) -> Result<(), String> {
    unsafe {
        let cpath = CString::new(path).map_err(|e| e.to_string())?;
        let mut db: *mut sqlite3 = ptr::null_mut();
        let rc = sqlite3_open(cpath.as_ptr(), &mut db);
        if rc != SQLITE_OK {
            let msg = errmsg(db);
            sqlite3_close(db);
            return Err(format!("{}: {}", msg, path));
        }
        let sql = CString::new(CREATE_TABLE).unwrap();
        let mut err: *mut c_char = ptr::null_mut();
        let rc = sqlite3_exec(db, sql.as_ptr(), ptr::null(), ptr::null_mut(), &mut err);
        if rc != SQLITE_OK {
            let msg = if err.is_null() {
                errmsg(db)
            } else {
                let m = CStr::from_ptr(err).to_string_lossy().into_owned();
                sqlite3_free(err as *mut c_void);
                m
            };
            sqlite3_close(db);
            return Err(msg);
        }
        let begin = CString::new("BEGIN").unwrap();
        sqlite3_exec(db, begin.as_ptr(), ptr::null(), ptr::null_mut(), ptr::null_mut());
        let insert = CString::new(
            "INSERT INTO oha (url, start, start_latency_correction, end, duration, status, len_bytes, run) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
        )
        .unwrap();
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let rc = sqlite3_prepare_v2(db, insert.as_ptr(), -1, &mut stmt, ptr::null_mut());
        if rc != SQLITE_OK {
            let msg = errmsg(db);
            sqlite3_close(db);
            return Err(msg);
        }
        let run = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        for r in results {
            let url = CString::new(r.url_path.as_str()).unwrap_or_default();
            sqlite3_bind_text(stmt, 1, url.as_ptr(), -1, SQLITE_TRANSIENT);
            sqlite3_bind_double(stmt, 2, r.start.saturating_duration_since(start).as_secs_f64());
            match r.start_latency_correction {
                Some(s) => {
                    sqlite3_bind_double(stmt, 3, s.saturating_duration_since(start).as_secs_f64());
                }
                None => {
                    sqlite3_bind_null(stmt, 3);
                }
            }
            sqlite3_bind_double(stmt, 4, r.end.saturating_duration_since(start).as_secs_f64());
            sqlite3_bind_double(stmt, 5, r.duration().as_secs_f64());
            sqlite3_bind_int64(stmt, 6, r.status as i64);
            sqlite3_bind_int64(stmt, 7, r.len_bytes as i64);
            sqlite3_bind_int64(stmt, 8, run);
            let rc = sqlite3_step(stmt);
            if rc != SQLITE_DONE {
                let msg = errmsg(db);
                sqlite3_finalize(stmt);
                sqlite3_close(db);
                return Err(msg);
            }
            sqlite3_reset(stmt);
        }
        sqlite3_finalize(stmt);
        let commit = CString::new("COMMIT").unwrap();
        sqlite3_exec(db, commit.as_ptr(), ptr::null(), ptr::null_mut(), ptr::null_mut());
        sqlite3_close(db);
        Ok(())
    }
}
