//! Load generation scheduling.
use crate::client::{Client, ClientConfig, ClientError, RequestResult};
use crossbeam_channel::{Receiver, Sender};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug)]
pub enum Mode {
    Count(usize),
    Duration(Duration),
}

#[derive(Clone, Copy, Debug)]
pub enum Rate {
    Unlimited,
    Qps(f64),
    Burst { delay: Duration, rate: usize },
}

pub struct WorkSetup {
    pub config: Arc<ClientConfig>,
    pub n_connections: usize,
    pub n_parallel: usize,
    pub mode: Mode,
    pub rate: Rate,
    pub latency_correction: bool,
    pub start: Instant,
    pub stop: Arc<AtomicBool>,
}

pub type Report = Result<RequestResult, ClientError>;

fn sleep_until(t: Instant) {
    let now = Instant::now();
    if t > now {
        std::thread::sleep(t - now);
    }
}

/// Spawns the scheduler/worker threads. The returned handles complete when all work is done.
pub fn spawn(setup: WorkSetup, report_tx: Sender<Report>) -> Vec<JoinHandle<()>> {
    let mut handles = Vec::new();
    let n_workers = if setup.config.is_http2() {
        setup.n_connections * setup.n_parallel.max(1)
    } else {
        setup.n_connections
    };
    let deadline = match setup.mode {
        Mode::Duration(d) => Some(setup.start + d),
        Mode::Count(_) => None,
    };
    match setup.rate {
        Rate::Unlimited => match setup.mode {
            Mode::Count(n) => {
                let counter = Arc::new(AtomicUsize::new(0));
                for _ in 0..n_workers {
                    let config = setup.config.clone();
                    let counter = counter.clone();
                    let tx = report_tx.clone();
                    let stop = setup.stop.clone();
                    handles.push(std::thread::spawn(move || {
                        let mut client = Client::new(config);
                        loop {
                            if stop.load(Ordering::Relaxed) {
                                break;
                            }
                            if counter.fetch_add(1, Ordering::Relaxed) >= n {
                                break;
                            }
                            let r = client.work(None);
                            if tx.send(r).is_err() {
                                break;
                            }
                        }
                    }));
                }
            }
            Mode::Duration(_) => {
                let deadline = deadline.unwrap();
                for _ in 0..n_workers {
                    let config = setup.config.clone();
                    let tx = report_tx.clone();
                    let stop = setup.stop.clone();
                    handles.push(std::thread::spawn(move || {
                        let mut client = Client::new(config);
                        loop {
                            if stop.load(Ordering::Relaxed) || Instant::now() >= deadline {
                                break;
                            }
                            let r = client.work(None);
                            if tx.send(r).is_err() {
                                break;
                            }
                        }
                    }));
                }
            }
        },
        Rate::Qps(_) | Rate::Burst { .. } => {
            let (token_tx, token_rx): (Sender<Instant>, Receiver<Instant>) = crossbeam_channel::unbounded();
            // scheduler
            {
                let rate = setup.rate;
                let mode = setup.mode;
                let start = setup.start;
                let stop = setup.stop.clone();
                handles.push(std::thread::spawn(move || {
                    let mut sent = 0usize;
                    let limit = match mode {
                        Mode::Count(n) => Some(n),
                        Mode::Duration(_) => None,
                    };
                    let sched_start = Instant::now();
                    match rate {
                        Rate::Qps(qps) => {
                            let mut i: u64 = 0;
                            loop {
                                if stop.load(Ordering::Relaxed) {
                                    break;
                                }
                                if let Some(n) = limit {
                                    if sent >= n {
                                        break;
                                    }
                                }
                                let t = sched_start + Duration::from_secs_f64(i as f64 / qps);
                                if let Some(d) = deadline {
                                    if t >= d {
                                        break;
                                    }
                                }
                                sleep_until(t);
                                if stop.load(Ordering::Relaxed) {
                                    break;
                                }
                                if token_tx.send(Instant::now()).is_err() {
                                    break;
                                }
                                sent += 1;
                                i += 1;
                            }
                        }
                        Rate::Burst { delay, rate } => {
                            let mut next = sched_start + delay;
                            'outer: loop {
                                if stop.load(Ordering::Relaxed) {
                                    break;
                                }
                                if let Some(d) = deadline {
                                    if next >= d {
                                        break;
                                    }
                                }
                                sleep_until(next);
                                next += delay;
                                let now = Instant::now();
                                for _ in 0..rate {
                                    if let Some(n) = limit {
                                        if sent >= n {
                                            break 'outer;
                                        }
                                    }
                                    if token_tx.send(now).is_err() {
                                        break 'outer;
                                    }
                                    sent += 1;
                                }
                                if let Some(n) = limit {
                                    if sent >= n {
                                        break;
                                    }
                                }
                            }
                        }
                        Rate::Unlimited => unreachable!(),
                    }
                    let _ = start;
                    drop(token_tx);
                }));
            }
            for _ in 0..n_workers {
                let config = setup.config.clone();
                let tx = report_tx.clone();
                let rx = token_rx.clone();
                let stop = setup.stop.clone();
                let latency_correction = setup.latency_correction;
                handles.push(std::thread::spawn(move || {
                    let mut client = Client::new(config);
                    loop {
                        if stop.load(Ordering::Relaxed) {
                            break;
                        }
                        let token = match deadline {
                            Some(d) => {
                                let now = Instant::now();
                                if now >= d {
                                    break;
                                }
                                match rx.recv_timeout(d - now) {
                                    Ok(t) => t,
                                    Err(crossbeam_channel::RecvTimeoutError::Timeout) => break,
                                    Err(_) => break,
                                }
                            }
                            None => match rx.recv() {
                                Ok(t) => t,
                                Err(_) => break,
                            },
                        };
                        let slc = if latency_correction { None } else { Some(token) };
                        let r = client.work(slc);
                        if tx.send(r).is_err() {
                            break;
                        }
                    }
                }));
            }
        }
    }
    handles
}
EOF
echo ok"}

