use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug)]
pub enum Mode {
    Count(usize),
    Duration(Duration),
}

#[derive(Clone, Copy, Debug)]
pub enum Rate {
    Unlimited,
    Qps(f64),
    Burst { delay: Duration, rate: usize },
}

pub struct WorkSetup {
    pub config: Arc<ClientConfig>,
    pub n_connections: usize,
    pub n_parallel: usize,
    pub mode: Mode,
    pub rate: Rate,
    pub latency_correction: bool,
    pub start: Instant,
    pub stop: Arc<AtomicBool>,
}

pub type Report = Result<RequestResult, ClientError>;

fn sleep_until(t: Instant) {
    let now = Instant::now();
    if t > now {
        std::thread::sleep(t - now);
    }
}

/// Spawns the scheduler/worker threads. The returned handles complete when all work is done.
pub fn spawn(setup: WorkSetup, report_tx: Sender<Report>) -> Vec<JoinHandle<()>> {
    let mut handles = Vec::new();
    let n_workers = if setup.config.is_http2() {
        setup.n_connections * setup.n_parallel.max(1)
    } else {
        setup.n_connections
    };
    let deadline = match setup.mode {
        Mode::Duration(d) => Some(setup.start + d),
        Mode::Count(_) => None,
    };
    match setup.rate {
        Rate::Unlimited => match setup.mode {
            Mode::Count(n) => {
                let counter = Arc::new(AtomicUsize::new(0));
                for _ in 0..n_workers {
                    let config = setup.config.clone();
                    let counter = counter.clone();
                    let tx = report_tx.clone();
                    let stop = setup.stop.clone();
