output.arguments:
{"command":"cat > /workspace/src/main.rs <<'EOF'
mod aws;
mod cli;
mod client;
mod db;
mod debug;
mod dns;
mod duration;
mod form;
mod http2;
mod parse;
mod printer;
mod rand_regex;
mod result_data;
mod tls;
mod tls_config;
mod tui;
mod url_generator;
mod work;

use anyhow::{anyhow, bail};
use client::{Body, ClientConfig, HttpVersion};
use printer::{OutputFormat, TimeUnit};
use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

static INTERRUPTED: AtomicBool = AtomicBool::new(false);

extern "C" fn on_sigint(_: libc::c_int) {
    INTERRUPTED.store(true, Ordering::SeqCst);
}

fn install_sigint_handler() {
    unsafe {
        libc::signal(libc::SIGINT, on_sigint as usize);
    }
}

pub enum Output {
    Stdout,
    File(std::fs::File),
}

impl Write for Output {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self {
            Output::Stdout => std::io::stdout().write(buf),
            Output::File(f) => f.write(buf),
        }
    }
    fn flush(&mut self) -> std::io::Result<()> {
        match self {
            Output::Stdout => std::io::stdout().flush(),
            Output::File(f) => f.flush(),
        }
    }
}

fn main() {
    match run() {
        Ok(()) => {}
        Err(e) => {
            eprintln!("Error: {:?}", e);
            std::process::exit(1);
        }
    }
}

fn parse_http_version(flag_http2: bool, version: Option<&String>) -> anyhow::Result<HttpVersion> {
    if flag_http2 && version.is_some() {
        bail!("--http2 and --http-version are exclusive");
    }
    if flag_http2 {
        return Ok(HttpVersion::Http2);
    }
    match version {
        Some(v) => {
            let v = HttpVersion::parse(v)
                .ok_or_else(|| anyhow!("Unknown HTTP version. Valid versions are 0.9, 1.0, 1.1, 2, 3"))?;
            if v == HttpVersion::Http3 {
                bail!("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.");
            }
            Ok(v)
        }
        None => Ok(HttpVersion::Http11),
    }
}

fn run() -> anyhow::Result<()> {
    let matches = cli::build_command().get_matches();

    let http_version = parse_http_version(
        matches.get_flag("http2"),
        matches.get_one::<String>("http_version"),
    )?;
    let proxy_http_version = parse_http_version(
        matches.get_flag("proxy_http2"),
        matches.get_one::<String>("proxy_http_version"),
    )?;

    // AWS SigV4
    let aws_sigv4 = matches.get_one::<String>("aws_sigv4").cloned();
    let basic_auth = matches.get_one::<String>("basic_auth").cloned();
    let aws_session = matches.get_one::<String>("aws_session").cloned();
    let mut aws_config: Option<client::AwsConfig> = None;
    if let Some(params) = &aws_sigv4 {
        let auth = basic_auth
            .as_ref()
            .ok_or_else(|| anyhow!("AWS credentials (--auth) required when using --aws-sigv4"))?;
        let (access_key, secret_key) = auth
            .split_once(':')
            .ok_or_else(|| anyhow!("Invalid AWS credentials format. Expected access_key:secret_key"))?;
        let parts: Vec<&str> = params.split(':').collect();
        if parts.len() != 4 || parts[0] != "aws" || parts[1] != "amz" {
            bail!("Invalid AWS signing params format. Expected aws:amz:region:service");
        }
        aws_config = Some(client::AwsConfig {
            access_key: access_key.to_string(),
            secret_key: secret_key.to_string(),
            session_token: aws_session.clone(),
            region: parts[2].to_string(),
            service: parts[3].to_string(),
        });
    }

    // URL generator
    let url_arg = matches.get_one::<String>("url").unwrap().clone();
    let url_generator = if matches.get_flag("urls_from_file") {
        url_generator::UrlGenerator::from_file(&url_arg)?
    } else if matches.get_flag("rand_regex_url") {
        let max_repeat = *matches.get_one::<u32>("max_repeat").unwrap();
        let pattern = url_arg.replace('.', "\\.");
        let regex = rand_regex::RandRegex::compile(&pattern, max_repeat)?;
        url_generator::UrlGenerator::new_dynamic(regex)
    } else {
        url_generator::UrlGenerator::new_static(url::Url::parse(&url_arg)?)
    };
    let url_generator = Arc::new(url_generator);

    if let Some(n) = matches.get_one::<usize>("dump_urls") {
        let mut rng = rand::thread_rng();
        let stdout = std::io::stdout();
        let mut out = stdout.lock();
        for _ in 0..*n {
            let url = url_generator.generate(&mut rng)?;
            writeln!(out, "{}", url)?;
        }
        return Ok(());
    }

    // Headers
    let mut headers: Vec<(String, String)> = Vec::new();
    let insert = |headers: &mut Vec<(String, String)>, k: &str, v: &str| {
        if let Some(e) = headers.iter_mut().find(|(n, _)| n == k) {
            e.1 = v.to_string();
        } else {
            headers.push((k.to_string(), v.to_string()));
        }
    };
    insert(&mut headers, "accept", "*/*");
    if !matches.get_flag("disable_compression") {
        insert(&mut headers, "accept-encoding", "gzip, compress, deflate, br");
    }
    insert(&mut headers, "user-agent", &format!("oha/{}", cli::VERSION));
    if let Some(a) = matches.get_one::<String>("accept_header") {
        insert(&mut headers, "accept", a);
    }
    if let Some(ct) = matches.get_one::<String>("content_type") {
        insert(&mut headers, "content-type", ct);
    }

    // Body
    let mut method = matches.get_one::<String>("method").unwrap().clone();
    let body: Body = if let Some(s) = matches.get_one::<String>("body_string") {
        if s.is_empty() {
            Body::Empty
        } else {
            Body::Static(Arc::new(s.as_bytes().to_vec()))
        }
    } else if let Some(p) = matches.get_one::<std::path::PathBuf>("body_path") {
        let data = std::fs::read(p)?;
        if data.is_empty() {
            Body::Empty
        } else {
            Body::Static(Arc::new(data))
        }
    } else if let Some(p) = matches.get_one::<std::path::PathBuf>("body_path_lines") {
        let content = std::fs::read_to_string(p)?;
        let lines: Vec<Vec<u8>> = content.lines().map(|l| l.as_bytes().to_vec()).collect();
        if lines.is_empty() {
            Body::Empty
        } else {
            Body::Lines(Arc::new(lines))
        }
    } else if let Some(forms) = matches.get_many::<String>("form") {
        let specs: Vec<String> = forms.cloned().collect();
        let mp = form::build(&specs).map_err(|e| anyhow!("{}", e))?;
        insert(&mut headers, "content-type", &mp.content_type);
        if method == "GET" {
            method = "POST".to_string();
        }
        Body::Static(Arc::new(mp.body))
    } else {
        Body::Empty
    };

    // TLS config
    let insecure = matches.get_flag("insecure");
    let cacert = matches.get_one::<String>("cacert").cloned();
    let cert = matches.get_one::<String>("cert").cloned();
    let key = matches.get_one::<String>("key").cloned();
    let tls = tls_config::build(insecure, cacert, cert, key, http_version == HttpVersion::Http2)?;

    if let Some(host) = matches.get_one::<String>("host") {
        insert(&mut headers, "host", host);
    }
    if aws_config.is_none() {
        if let Some(auth) = &basic_auth {
            let (user, pass) = auth.split_once(':').ok_or_else(|| anyhow!("Parse auth"))?;
            use base64::Engine;
            let encoded = base64::engine::general_purpose::STANDARD.encode(format!("{}:{}", user, pass));
            insert(&mut headers, "authorization", &format!("Basic {}", encoded));
        }
    }
    if let Some(hs) = matches.get_many::<parse::Header>("headers") {
        for h in hs {
            insert(&mut headers, &h.name, &h.value);
        }
    }
    let disable_keepalive = matches.get_flag("disable_keepalive");
    if disable_keepalive && http_version != HttpVersion::Http2 {
        insert(&mut headers, "connection", "close");
    }
    let proxy_headers: Vec<(String, String)> = matches
        .get_many::<parse::Header>("proxy_headers")
        .map(|hs| hs.map(|h| (h.name.clone(), h.value.clone())).collect())
        .unwrap_or_default();

    // DNS
    let strategy = if matches.get_flag("ipv4") {
        dns::IpStrategy::Ipv4Only
    } else if matches.get_flag("ipv6") {
        dns::IpStrategy::Ipv6Only
    } else {
        dns::IpStrategy::Both
    };
    let connect_to: Vec<parse::ConnectToEntry> = matches
        .get_many::<parse::ConnectToEntry>("connect_to")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let resolver = Arc::new(dns::Resolver::new(strategy, connect_to));
    let unix_socket = matches.get_one::<std::path::PathBuf>("unix_socket").cloned();
    let proxy_url = matches.get_one::<url::Url>("proxy").cloned();

    if !matches.get_flag("no_pre_lookup") {
        if let Some(url) = url_generator.static_url() {
            let skip = unix_socket.is_some() && url.scheme() != "https";
            if !skip {
                if let Some(host) = url.host_str() {
                    let port = url.port_or_known_default().unwrap_or(80);
                    let mut rng = rand::thread_rng();
                    let (target_host, _) = resolver.connect_target(host, port, &mut rng);
                    resolver.cache_lookup(&target_host)?;
                }
            }
        }
    }

    // Output
    let output_format = match matches.get_one::<String>("output_format").unwrap().as_str() {
        "text" => OutputFormat::Text,
        "json" => OutputFormat::Json,
        "csv" => OutputFormat::Csv,
        _ => OutputFormat::Quiet,
    };
    let mut output = match matches.get_one::<std::path::PathBuf>("output") {
        Some(p) => Output::File(std::fs::File::create(p)?),
        None => Output::Stdout,
    };
    let time_unit = matches
        .get_one::<String>("time_unit")
        .and_then(|s| TimeUnit::from_arg(s));
    let stats_success_breakdown = matches.get_flag("stats_success_breakdown");
    let disable_color = matches.get_flag("no_color");

    let n_requests = *matches.get_one::<usize>("n_requests").unwrap();
    let n_connections = *matches.get_one::<usize>("n_connections").unwrap();
    let n_parallel = *matches.get_one::<usize>("n_http2_parallel").unwrap();
    let duration = matches.get_one::<Duration>("duration").copied();
    let wait_ongoing = matches.get_flag("wait_ongoing_requests_after_deadline");
    let qps = matches.get_one::<f64>("query_per_second").copied();
    let burst_delay = matches.get_one::<Duration>("burst_delay").copied();
    let burst_rate = matches.get_one::<usize>("burst_rate").copied();
    let latency_correction = matches.get_flag("latency_correction");
    let fps = *matches.get_one::<usize>("fps").unwrap();
    let no_tui = matches.get_flag("no_tui");
    let db_url = matches.get_one::<String>("db_url").cloned();

    let start = Instant::now();
    let deadline = duration.map(|d| start + d);

    let config = Arc::new(ClientConfig {
        http_version,
        proxy_http_version,
        url_generator: url_generator.clone(),
        method,
        headers,
        body,
        timeout: matches.get_one::<Duration>("timeout").copied(),
        connect_timeout: *matches.get_one::<Duration>("connect_timeout").unwrap(),
        redirect_limit: *matches.get_one::<usize>("redirect").unwrap(),
        disable_keepalive,
        insecure,
        tls: tls.map(Arc::new),
        proxy_url,
        proxy_headers,
        unix_socket,
        resolver,
        aws: aws_config,
        deadline,
        wait_ongoing_requests_after_deadline: wait_ongoing,
        http2_parallel: n_parallel,
    });

    if matches.get_flag("debug") {
        let mut client = client::Client::new(config.clone());
        let via_proxy = config.proxy_url.is_some() && config.url_generator.static_url().map(|u| u.scheme() != "https").unwrap_or(true);
        // Print request first (using the generated URL), then perform it.
        let result = client.debug_request();
        match result {
            Ok((url, headers, body, resp)) => {
                debug::write_request(
                    &mut output,
                    &config.method,
                    &url,
                    config.http_version,
                    &headers,
                    body.as_deref(),
                    via_proxy || config.is_http2(),
                )?;
                debug::write_response(&mut output, &resp)?;
                output.flush()?;
            }
            Err(e) => {
                // The request is dumped even when the request fails.
                if let Ok(url) = config.url_generator.generate(&mut client.rng) {
                    let body = client.pick_body();
                    let headers = client.build_headers(&url, via_proxy, body.as_deref());
                    debug::write_request(
                        &mut output,
                        &config.method,
                        &url,
                        config.http_version,
                        &headers,
                        body.as_deref(),
                        via_proxy || config.is_http2(),
                    )?;
                    output.flush()?;
                }
                return Err(anyhow!("{}", e));
            }
        }
        return Ok(());
    }

    let mode = match duration {
        Some(d) => work::Mode::Duration(d),
        None => work::Mode::Count(n_requests),
    };
    let rate = if let Some(q) = qps {
        work::Rate::Qps(q)
    } else if let (Some(delay), Some(rate)) = (burst_delay, burst_rate) {
        work::Rate::Burst { delay, rate }
    } else {
        work::Rate::Unlimited
    };

    let stop = Arc::new(AtomicBool::new(false));
    let (report_tx, report_rx) = crossbeam_channel::unbounded::<work::Report>();
    let setup = work::WorkSetup {
        config: config.clone(),
        n_connections,
        n_parallel,
        mode,
        rate,
        latency_correction,
        start,
        stop: stop.clone(),
    };
    let handles = work::spawn(setup, report_tx);

