static INTERRUPTED: AtomicBool = AtomicBool::new(false);

extern "C" fn on_sigint(_: libc::c_int) {
    INTERRUPTED.store(true, Ordering::SeqCst);
}

fn install_sigint_handler() {
    unsafe {
        libc::signal(libc::SIGINT, on_sigint as usize);
    }
}

pub enum Output {
    Stdout,
    File(std::fs::File),
}

impl Write for Output {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self {
            Output::Stdout => std::io::stdout().write(buf),
            Output::File(f) => f.write(buf),
        }
    }
    fn flush(&mut self) -> std::io::Result<()> {
        match self {
            Output::Stdout => std::io::stdout().flush(),
            Output::File(f) => f.flush(),
        }
    }
}

fn main() {
    match run() {
        Ok(()) => {}
        Err(e) => {
            eprintln!("Error: {:?}", e);
            std::process::exit(1);
        }
    }
}

fn parse_http_version(flag_http2: bool, version: Option<&String>) -> anyhow::Result<HttpVersion> {
    if flag_http2 && version.is_some() {
        bail!("--http2 and --http-version are exclusive");
    }
    if flag_http2 {
        return Ok(HttpVersion::Http2);
    }
    match version {
        Some(v) => {
            let v = HttpVersion::parse(v)
                .ok_or_else(|| anyhow!("Unknown HTTP version. Valid versions are 0.9, 1.0, 1.1, 2, 3"))?;
            if v == HttpVersion::Http3 {
                bail!("Your Oha instance has not been built with HTTP/3 support. Try recompiling with the feature enabled.");
            }
            Ok(v)
        }
        None => Ok(HttpVersion::Http11),
    }
}

fn run() -> anyhow::Result<()> {
    let matches = cli::build_command().get_matches();

    let http_version = parse_http_version(
        matches.get_flag("http2"),
        matches.get_one::<String>("http_version"),
    )?;
    let proxy_http_version = parse_http_version(
        matches.get_flag("proxy_http2"),
        matches.get_one::<String>("proxy_http_version"),
    )?;

