    let aws_sigv4 = matches.get_one::<String>("aws_sigv4").cloned();
    let basic_auth = matches.get_one::<String>("basic_auth").cloned();
    let aws_session = matches.get_one::<String>("aws_session").cloned();
    let mut aws_config: Option<client::AwsConfig> = None;
    if let Some(params) = &aws_sigv4 {
        let auth = basic_auth
            .as_ref()
            .ok_or_else(|| anyhow!("AWS credentials (--auth) required when using --aws-sigv4"))?;
        let (access_key, secret_key) = auth
            .split_once(':')
            .ok_or_else(|| anyhow!("Invalid AWS credentials format. Expected access_key:secret_key"))?;
        let parts: Vec<&str> = params.split(':').collect();
        if parts.len() != 4 || parts[0] != "aws" || parts[1] != "amz" {
            bail!("Invalid AWS signing params format. Expected aws:amz:region:service");
        }
        aws_config = Some(client::AwsConfig {
            access_key: access_key.to_string(),
            secret_key: secret_key.to_string(),
            session_token: aws_session.clone(),
            region: parts[2].to_string(),
            service: parts[3].to_string(),
        });
    }

    // URL generator
    let url_arg = matches.get_one::<String>("url").unwrap().clone();
    let url_generator = if matches.get_flag("urls_from_file") {
        url_generator::UrlGenerator::from_file(&url_arg)?
    } else if matches.get_flag("rand_regex_url") {
        let max_repeat = *matches.get_one::<u32>("max_repeat").unwrap();
        let pattern = url_arg.replace('.', "\\.");
        let regex = rand_regex::RandRegex::compile(&pattern, max_repeat)?;
        url_generator::UrlGenerator::new_dynamic(regex)
    } else {
        url_generator::UrlGenerator::new_static(url::Url::parse(&url_arg)?)
    };
    let url_generator = Arc::new(url_generator);

    if let Some(n) = matches.get_one::<usize>("dump_urls") {
        let mut rng = rand::thread_rng();
        let stdout = std::io::stdout();
        let mut out = stdout.lock();
        for _ in 0..*n {
            let url = url_generator.generate(&mut rng)?;
            writeln!(out, "{}", url)?;
        }
        return Ok(());
    }

    // Headers
    let mut headers: Vec<(String, String)> = Vec::new();
    let insert = |headers: &mut Vec<(String, String)>, k: &str, v: &str| {
        if let Some(e) = headers.iter_mut().find(|(n, _)| n == k) {
            e.1 = v.to_string();
        } else {
            headers.push((k.to_string(), v.to_string()));
        }
    };
    insert(&mut headers, "accept", "*/*");
    if !matches.get_flag("disable_compression") {
        insert(&mut headers, "accept-encoding", "gzip, compress, deflate, br");
    }
    insert(&mut headers, "user-agent", &format!("oha/{}", cli::VERSION));
    if let Some(a) = matches.get_one::<String>("accept_header") {
        insert(&mut headers, "accept", a);
    }
    if let Some(ct) = matches.get_one::<String>("content_type") {
        insert(&mut headers, "content-type", ct);
    }

    // Body
    let mut method = matches.get_one::<String>("method").unwrap().clone();
    let body: Body = if let Some(s) = matches.get_one::<String>("body_string") {
        if s.is_empty() {
            Body::Empty
        } else {
            Body::Static(Arc::new(s.as_bytes().to_vec()))
        }
    } else if let Some(p) = matches.get_one::<std::path::PathBuf>("body_path") {
        let data = std::fs::read(p)?;
        if data.is_empty() {
            Body::Empty
        } else {
            Body::Static(Arc::new(data))
        }
    } else if let Some(p) = matches.get_one::<std::path::PathBuf>("body_path_lines") {
        let content = std::fs::read_to_string(p)?;
        let lines: Vec<Vec<u8>> = content.lines().map(|l| l.as_bytes().to_vec()).collect();
        if lines.is_empty() {
            Body::Empty
        } else {
            Body::Lines(Arc::new(lines))
        }
    } else if let Some(forms) = matches.get_many::<String>("form") {
        let specs: Vec<String> = forms.cloned().collect();
        let mp = form::build(&specs).map_err(|e| anyhow!("{}", e))?;
        insert(&mut headers, "content-type", &mp.content_type);
        if method == "GET" {
            method = "POST".to_string();
        }
        Body::Static(Arc::new(mp.body))
    } else {
        Body::Empty
    };

    // TLS config
    let insecure = matches.get_flag("insecure");
    let cacert = matches.get_one::<String>("cacert").cloned();
    let cert = matches.get_one::<String>("cert").cloned();
    let key = matches.get_one::<String>("key").cloned();
    let tls = tls_config::build(insecure, cacert, cert, key, http_version == HttpVersion::Http2)?;

