            let (user, pass) = auth.split_once(':').ok_or_else(|| anyhow!("Parse auth"))?;
            use base64::Engine;
            let encoded = base64::engine::general_purpose::STANDARD.encode(format!("{}:{}", user, pass));
            insert(&mut headers, "authorization", &format!("Basic {}", encoded));
        }
    }
    if let Some(hs) = matches.get_many::<parse::Header>("headers") {
        for h in hs {
            insert(&mut headers, &h.name, &h.value);
        }
    }
    let disable_keepalive = matches.get_flag("disable_keepalive");
    if disable_keepalive && http_version != HttpVersion::Http2 {
        insert(&mut headers, "connection", "close");
    }
    let proxy_headers: Vec<(String, String)> = matches
        .get_many::<parse::Header>("proxy_headers")
        .map(|hs| hs.map(|h| (h.name.clone(), h.value.clone())).collect())
        .unwrap_or_default();

    // DNS
    let strategy = if matches.get_flag("ipv4") {
        dns::IpStrategy::Ipv4Only
    } else if matches.get_flag("ipv6") {
        dns::IpStrategy::Ipv6Only
    } else {
        dns::IpStrategy::Both
    };
    let connect_to: Vec<parse::ConnectToEntry> = matches
        .get_many::<parse::ConnectToEntry>("connect_to")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let resolver = Arc::new(dns::Resolver::new(strategy, connect_to));
    let unix_socket = matches.get_one::<std::path::PathBuf>("unix_socket").cloned();
    let proxy_url = matches.get_one::<url::Url>("proxy").cloned();

    if !matches.get_flag("no_pre_lookup") {
        if let Some(url) = url_generator.static_url() {
            let skip = unix_socket.is_some() && url.scheme() != "https";
            if !skip {
                if let Some(host) = url.host_str() {
                    let port = url.port_or_known_default().unwrap_or(80);
                    let mut rng = rand::thread_rng();
                    let (target_host, _) = resolver.connect_target(host, port, &mut rng);
                    resolver.cache_lookup(&target_host)?;
                }
            }
        }
    }

    // Output
    let output_format = match matches.get_one::<String>("output_format").unwrap().as_str() {
        "text" => OutputFormat::Text,
        "json" => OutputFormat::Json,
        "csv" => OutputFormat::Csv,
        _ => OutputFormat::Quiet,
    };
    let mut output = match matches.get_one::<std::path::PathBuf>("output") {
        Some(p) => Output::File(std::fs::File::create(p)?),
        None => Output::Stdout,
    };
    let time_unit = matches
        .get_one::<String>("time_unit")
        .and_then(|s| TimeUnit::from_arg(s));
    let stats_success_breakdown = matches.get_flag("stats_success_breakdown");
    let disable_color = matches.get_flag("no_color");

    let n_requests = *matches.get_one::<usize>("n_requests").unwrap();
    let n_connections = *matches.get_one::<usize>("n_connections").unwrap();
    let n_parallel = *matches.get_one::<usize>("n_http2_parallel").unwrap();
    let duration = matches.get_one::<Duration>("duration").copied();
    let wait_ongoing = matches.get_flag("wait_ongoing_requests_after_deadline");
    let qps = matches.get_one::<f64>("query_per_second").copied();
    let burst_delay = matches.get_one::<Duration>("burst_delay").copied();
    let burst_rate = matches.get_one::<usize>("burst_rate").copied();
    let latency_correction = matches.get_flag("latency_correction");
    let fps = *matches.get_one::<usize>("fps").unwrap();
    let no_tui = matches.get_flag("no_tui");
    let db_url = matches.get_one::<String>("db_url").cloned();

    let start = Instant::now();
    let deadline = duration.map(|d| start + d);

    let config = Arc::new(ClientConfig {
        http_version,
        proxy_http_version,
        url_generator: url_generator.clone(),
        method,
        headers,
        body,
        timeout: matches.get_one::<Duration>("timeout").copied(),
        connect_timeout: *matches.get_one::<Duration>("connect_timeout").unwrap(),
