        let mut client = client::Client::new(config.clone());
        let via_proxy = config.proxy_url.is_some() && config.url_generator.static_url().map(|u| u.scheme() != "https").unwrap_or(true);
        // Print request first (using the generated URL), then perform it.
        let result = client.debug_request();
        match result {
            Ok((url, headers, body, resp)) => {
                debug::write_request(
                    &mut output,
                    &config.method,
                    &url,
                    config.http_version,
                    &headers,
                    body.as_deref(),
                    via_proxy || config.is_http2(),
                )?;
                debug::write_response(&mut output, &resp)?;
                output.flush()?;
            }
            Err(e) => {
                // The request is dumped even when the request fails.
                if let Ok(url) = config.url_generator.generate(&mut client.rng) {
                    let body = client.pick_body();
                    let headers = client.build_headers(&url, via_proxy, body.as_deref());
                    debug::write_request(
                        &mut output,
                        &config.method,
                        &url,
                        config.http_version,
                        &headers,
                        body.as_deref(),
                        via_proxy || config.is_http2(),
                    )?;
                    output.flush()?;
                }
                return Err(anyhow!("{}", e));
            }
        }
        return Ok(());
    }

    let mode = match duration {
        Some(d) => work::Mode::Duration(d),
        None => work::Mode::Count(n_requests),
    };
    let rate = if let Some(q) = qps {
        work::Rate::Qps(q)
    } else if let (Some(delay), Some(rate)) = (burst_delay, burst_rate) {
        work::Rate::Burst { delay, rate }
    } else {
        work::Rate::Unlimited
    };

    let stop = Arc::new(AtomicBool::new(false));
    let (report_tx, report_rx) = crossbeam_channel::unbounded::<work::Report>();
    let setup = work::WorkSetup {
        config: config.clone(),
        n_connections,
        n_parallel,
        mode,
        rate,
        latency_correction,
        start,
        stop: stop.clone(),
    };
    let handles = work::spawn(setup, report_tx);

