                Err(crossbeam_channel::RecvTimeoutError::Timeout) => continue,
                Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
            }
        }
        total_duration = start.elapsed();
    }
    drop(handles);

    if let Some(db) = &db_url {
        eprintln!("Storing results to {}", db);
        db::store(db, start, &res.success).map_err(|e| anyhow!("{}", e))?;
    }

    match output_format {
        OutputFormat::Text => printer::print_text(
            &mut output,
            &res,
            total_duration,
            time_unit,
            stats_success_breakdown,
            disable_color,
        )?,
        OutputFormat::Json => printer::print_json(&mut output, &res, start, total_duration, stats_success_breakdown)?,
        OutputFormat::Csv => printer::print_csv(&mut output, &res, start)?,
        OutputFormat::Quiet => {}
    }
    output.flush()?;
    // Do not wait for worker threads (they may be blocked in I/O).
    std::process::exit(0);
}

