            rl.rlim_cur as u64
        } else {
            0
        }
    };
    (count, limit)
}

struct Ui {
    scale: Option<TimeScale>, // None = auto
}

pub fn run(
    report_rx: Receiver<Report>,
    res: &mut ResultData,
    start: Instant,
    mode: Mode,
    fps: usize,
    disable_color: bool,
    stop: Arc<AtomicBool>,
) -> anyhow::Result<Duration> {
    let mut terminal = ratatui::try_init()?;
    let frame_time = Duration::from_secs_f64(1.0 / (fps.max(1) as f64));
    let mut ui = Ui { scale: None };
    let mut done = false;
    let result = loop {
        // Drain results
        loop {
            match report_rx.try_recv() {
                Ok(r) => res.push(r.map_err(|e| e.to_string())),
                Err(crossbeam_channel::TryRecvError::Empty) => break,
                Err(crossbeam_channel::TryRecvError::Disconnected) => {
                    done = true;
                    break;
                }
            }
        }
        if done {
            break Ok(start.elapsed());
        }
        let frame_start = Instant::now();
        let draw_result = terminal.draw(|f| draw(f, res, start, mode, &ui, disable_color));
        if let Err(e) = draw_result {
            break Err(anyhow::anyhow!("{}", e));
        }
        // Handle input until the next frame
        let mut quit = false;
        loop {
            let elapsed = frame_start.elapsed();
            let remaining = frame_time.saturating_sub(elapsed);
            if remaining.is_zero() {
                break;
            }
            match event::poll(remaining) {
                Ok(true) => match event::read() {
                    Ok(Event::Key(k)) if k.kind != KeyEventKind::Release => match k.code {
                        KeyCode::Char('q') => quit = true,
                        KeyCode::Char('c') if k.modifiers.contains(KeyModifiers::CONTROL) => quit = true,
                        KeyCode::Char('+') => {
                            let cur = ui.scale.unwrap_or_else(|| current_auto(start, &terminal));
                            ui.scale = Some(cur.finer());
                        }
                        KeyCode::Char('-') => {
                            let cur = ui.scale.unwrap_or_else(|| current_auto(start, &terminal));
                            ui.scale = Some(cur.coarser());
                        }
                        KeyCode::Char('a') => ui.scale = None,
                        _ => {}
                    },
                    Ok(_) => {}
                    Err(_) => {}
                },
                Ok(false) => break,
                Err(_) => break,
            }
            if quit {
                break;
            }
        }
        if quit {
            stop.store(true, Ordering::Relaxed);
            break Ok(start.elapsed());
        }
    };
    ratatui::restore();
    result
}

fn current_auto(start: Instant, terminal: &ratatui::DefaultTerminal) -> TimeScale {
    let width = terminal.size().map(|s| s.width).unwrap_or(80) as usize;
    let inner = (width / 2).saturating_sub(2);
    let n_bars = ((inner + 1) / 6).max(1);
    TimeScale::auto(start.elapsed(), n_bars)
}

fn format_bytes(b: f64) -> String {
    crate::printer::format_bytes(b)
}

fn draw(f: &mut ratatui::Frame, res: &ResultData, start: Instant, mode: Mode, ui: &Ui, disable_color: bool) {
    let area = f.area();
    let now = Instant::now();
    let elapsed = now.saturating_duration_since(start);

    let errors = res.error_distribution_sorted();
    let error_height = (errors.len() as u16).saturating_add(2);
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(8),
            Constraint::Length(error_height),
            Constraint::Min(0),
        ])
        .split(area);

    let color = |c: Color| if disable_color { Style::default() } else { Style::default().fg(c) };

    // Progress gauge
    let (ratio, label) = match mode {
        Mode::Count(n) => {
            let count = res.total_requests();
            let ratio = if n == 0 { 1.0 } else { (count as f64 / n as f64).min(1.0) };
            (ratio, format!("{} / {}", count, n))
        }
        Mode::Duration(d) => {
            let ratio = if d.is_zero() { 1.0 } else { (elapsed.as_secs_f64() / d.as_secs_f64()).min(1.0) };
            (ratio, format!("{}s / {}s", elapsed.as_secs(), d.as_secs()))
        }
    };
    let gauge = Gauge::default()
        .block(Block::default().title("Progress").borders(Borders::ALL))
        .gauge_style(color(Color::Cyan))
        .label(label)
        .ratio(ratio.clamp(0.0, 1.0));
    f.render_widget(gauge, rows[0]);

    // Bars layout (needed to compute the auto scale)
    let bottom = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(rows[3]);
    let left_inner_width = bottom[0].width.saturating_sub(2) as usize;
    let right_inner_width = bottom[1].width.saturating_sub(2) as usize;

    let (scale, auto) = match ui.scale {
        Some(s) => (s, false),
        None => {
            let n_bars = ((left_inner_width + 1) / 6).max(1);
            (TimeScale::auto(elapsed, n_bars), true)
        }
    };
    let window = scale.duration();
    let window_start = now.checked_sub(window).unwrap_or(start);

    // Stats for last period
    let recent: Vec<&crate::client::RequestResult> = res
        .success
        .iter()
        .filter(|r| r.end >= window_start)
        .collect();
    let durations: Vec<f64> = recent.iter().map(|r| r.duration().as_secs_f64()).collect();
    let slowest = durations.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durations.iter().copied().fold(f64::INFINITY, f64::min);
    let average = durations.iter().sum::<f64>() / durations.len() as f64;
    let data: usize = recent.iter().map(|r| r.len_bytes).sum();
    let (nfiles, nlimit) = open_files();

    let middle = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(rows[1]);

    let stats_lines = vec![
        Line::from(format!("Requests : {}", recent.len())),
        Line::from(Span::styled(format!("Slowest: {:.4} secs", slowest), color(Color::Yellow))),
        Line::from(Span::styled(format!("Fastest: {:.4} secs", fastest), color(Color::Green))),
        Line::from(Span::styled(format!("Average: {:.4} secs", average), color(Color::Cyan))),
        Line::from(format!("Data: {}", format_bytes(data as f64))),
        Line::from(format!("Number of open files: {} / {}", nfiles, nlimit)),
    ];
    let stats = Paragraph::new(stats_lines).block(
        Block::default()
            .title(format!("Stats for last {}", scale.name()))
            .borders(Borders::ALL),
    );
    f.render_widget(stats, middle[0]);

    let status_lines: Vec<Line> = res
        .status_code_distribution()
        .into_iter()
        .map(|(code, count)| Line::from(format!("[{}] {} responses", code, count)))
        .collect();
    let status = Paragraph::new(status_lines).block(
        Block::default()
            .title("Status code distribution")
            .borders(Borders::ALL),
    );
    f.render_widget(status, middle[1]);

    let error_lines: Vec<Line> = errors
        .iter()
        .map(|(msg, count)| Line::from(format!("[{}] {}", count, msg)))
        .collect();
    let error_block = Paragraph::new(error_lines).block(
        Block::default()
            .title("Error distribution")
            .borders(Borders::ALL),
    );
    f.render_widget(error_block, rows[2]);

    // Requests per past period bar chart
    let scale_secs = window.as_secs_f64();
    let current_bucket = (elapsed.as_secs_f64() / scale_secs).floor() as i64;
    let label_width = scale.label(10).len().max(scale.label(0).len());
    let bar_width = (label_width + 3) as u16;
    let n_bars = ((left_inner_width + 1) / (bar_width as usize + 1)).max(1);
    let mut counts = vec![0u64; n_bars];
    for r in &res.success {
        let b = (r.end.saturating_duration_since(start).as_secs_f64() / scale_secs).floor() as i64;
        let idx = current_bucket - b;
        if idx >= 0 && (idx as usize) < n_bars {
            counts[idx as usize] += 1;
        }
    }
    let labels: Vec<String> = (0..n_bars).map(|i| scale.label(i)).collect();
    let bars: Vec<Bar> = counts
        .iter()
        .zip(labels.iter())
        .map(|(c, l)| Bar::default().value(*c).label(Line::from(l.as_str())))
        .collect();
    let title = if auto {
        format!("Requests / past {} (auto). press -/+/a to change", scale.name())
    } else {
        format!("Requests / past {}. press -/+/a to change", scale.name())
    };
    let chart = BarChart::default()
        .block(Block::default().title(title).borders(Borders::ALL))
        .data(BarGroup::default().bars(&bars))
        .bar_width(bar_width)
        .bar_gap(1)
        .style(color(Color::Green));
    f.render_widget(chart, bottom[0]);

    // Response time histogram
    let hist_bar_width: u16 = 7;
    let hist_bars = ((right_inner_width + 1) / (hist_bar_width as usize + 1)).max(1);
    let hist = histogram(&durations, hist_bars.saturating_sub(1).max(1));
    let hist_labels: Vec<String> = hist.iter().map(|(l, _)| format!("{:.4}", l)).collect();
    let hbars: Vec<Bar> = hist
        .iter()
        .zip(hist_labels.iter())
        .map(|((_, c), l)| Bar::default().value(*c as u64).label(Line::from(l.as_str())))
        .collect();
    let hchart = BarChart::default()
        .block(Block::default().title("Response time histogram").borders(Borders::ALL))
        .data(BarGroup::default().bars(&hbars))
        .bar_width(hist_bar_width)
        .bar_gap(1)
        .style(color(Color::Yellow));
    f.render_widget(hchart, bottom[1]);
}
