{"command":"cat > /workspace/src/hpack.rs <<'EOF'
//! Minimal HPACK (RFC 7541) encoder/decoder.
use crate::hpack_tables::{HUFFMAN_CODES, HUFFMAN_CODE_LENS, STATIC_TABLE};
use std::collections::VecDeque;

#[derive(Debug)]
pub struct HpackError;

struct HuffmanNode {
    children: [Option<usize>; 2],
    symbol: Option<u16>,
}

struct HuffmanTree {
    nodes: Vec<HuffmanNode>,
}

impl HuffmanTree {
    fn new() -> Self {
        let mut nodes = vec![HuffmanNode {
            children: [None, None],
            symbol: None,
        }];
        for sym in 0..257usize {
            let code = HUFFMAN_CODES[sym];
            let len = HUFFMAN_CODE_LENS[sym];
            let mut node = 0usize;
            for i in (0..len).rev() {
                let bit = ((code >> i) & 1) as usize;
                let next = match nodes[node].children[bit] {
                    Some(n) => n,
                    None => {
                        nodes.push(HuffmanNode {
                            children: [None, None],
                            symbol: None,
                        });
                        let idx = nodes.len() - 1;
                        nodes[node].children[bit] = Some(idx);
                        idx
                    }
                };
                node = next;
            }
            nodes[node].symbol = Some(sym as u16);
        }
        HuffmanTree { nodes }
    }

    fn decode(&self, data: &[u8]) -> Result<Vec<u8>, HpackError> {
        let mut out = Vec::with_capacity(data.len() * 2);
        let mut node = 0usize;
        let mut depth = 0u32;
        for &byte in data {
            for i in (0..8).rev() {
                let bit = ((byte >> i) & 1) as usize;
                node = self.nodes[node].children[bit].ok_or(HpackError)?;
                depth += 1;
                if let Some(sym) = self.nodes[node].symbol {
                    if sym == 256 {
                        return Err(HpackError); // EOS in string
                    }
                    out.push(sym as u8);
                    node = 0;
                    depth = 0;
                }
            }
        }
        // Remaining bits must be a prefix of EOS (all ones) and shorter than 8 bits.
        if depth > 7 {
            return Err(HpackError);
        }
        Ok(out)
    }
}

thread_local! {
    static HUFFMAN: HuffmanTree = HuffmanTree::new();
}

fn decode_integer(data: &[u8], pos: &mut usize, prefix_bits: u8) -> Result<usize, HpackError> {
    let max_prefix = (1usize << prefix_bits) - 1;
    let first = *data.get(*pos).ok_or(HpackError)? as usize & max_prefix;
    *pos += 1;
    if first < max_prefix {
        return Ok(first);
    }
    let mut value = first;
    let mut shift = 0u32;
    loop {
        let b = *data.get(*pos).ok_or(HpackError)?;
        *pos += 1;
        value = value
            .checked_add(((b & 0x7f) as usize) << shift)
            .ok_or(HpackError)?;
        if b & 0x80 == 0 {
            break;
        }
        shift += 7;
        if shift > 56 {
            return Err(HpackError);
        }
    }
    Ok(value)
}

fn decode_string(data: &[u8], pos: &mut usize) -> Result<Vec<u8>, HpackError> {
    let huffman = data.get(*pos).ok_or(HpackError)? & 0x80 != 0;
    let len = decode_integer(data, pos, 7)?;
    if *pos + len > data.len() {
        return Err(HpackError);
    }
    let raw = &data[*pos..*pos + len];
    *pos += len;
    if huffman {
        HUFFMAN.with(|h| h.decode(raw))
    } else {
        Ok(raw.to_vec())
    }
}

pub struct Decoder {
    dynamic: VecDeque<(Vec<u8>, Vec<u8>)>,
    size: usize,
    max_size: usize,
}

impl Default for Decoder {
    fn default() -> Self {
        Decoder {
            dynamic: VecDeque::new(),
            size: 0,
            max_size: 4096,
        }
    }
}

impl Decoder {
    fn entry(&self, index: usize) -> Result<(Vec<u8>, Vec<u8>), HpackError> {
        if index == 0 {
            return Err(HpackError);
        }
        if index <= STATIC_TABLE.len() {
            let (n, v) = STATIC_TABLE[index - 1];
            return Ok((n.as_bytes().to_vec(), v.as_bytes().to_vec()));
        }
        let idx = index - STATIC_TABLE.len() - 1;
        self.dynamic.get(idx).cloned().ok_or(HpackError)
    }

    fn add(&mut self, name: Vec<u8>, value: Vec<u8>) {
        let entry_size = name.len() + value.len() + 32;
        while self.size + entry_size > self.max_size {
            match self.dynamic.pop_back() {
                Some((n, v)) => self.size -= n.len() + v.len() + 32,
                None => break,
            }
        }
        if entry_size <= self.max_size {
            self.size += entry_size;
            self.dynamic.push_front((name, value));
        }
    }

    fn set_max_size(&mut self, max: usize) {
        self.max_size = max;
        while self.size > self.max_size {
            match self.dynamic.pop_back() {
                Some((n, v)) => self.size -= n.len() + v.len() + 32,
                None => break,
            }
        }
    }

    pub fn decode(&mut self, block: &[u8]) -> Result<Vec<(String, String)>, HpackError> {
        let mut pos = 0;
        let mut out = Vec::new();
        while pos < block.len() {
            let b = block[pos];
            if b & 0x80 != 0 {
                let idx = decode_integer(block, &mut pos, 7)?;
                let (n, v) = self.entry(idx)?;
                out.push((lossy(&n), lossy(&v)));
            } else if b & 0xc0 == 0x40 {
                let idx = decode_integer(block, &mut pos, 6)?;
                let name = if idx == 0 {
                    decode_string(block, &mut pos)?
                } else {
                    self.entry(idx)?.0
                };
                let value = decode_string(block, &mut pos)?;
                out.push((lossy(&name), lossy(&value)));
                self.add(name, value);
            } else if b & 0xe0 == 0x20 {
                let max = decode_integer(block, &mut pos, 5)?;
                self.set_max_size(max);
            } else {
                // literal without indexing (0000) or never indexed (0001)
                let idx = decode_integer(block, &mut pos, 4)?;
                let name = if idx == 0 {
                    decode_string(block, &mut pos)?
                } else {
                    self.entry(idx)?.0
                };
                let value = decode_string(block, &mut pos)?;
                out.push((lossy(&name), lossy(&value)));
            }
        }
        Ok(out)
    }
}

fn lossy(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

fn encode_integer(out: &mut Vec<u8>, value: usize, prefix_bits: u8, first_byte_flags: u8) {
    let max_prefix = (1usize << prefix_bits) - 1;
    if value < max_prefix {
        out.push(first_byte_flags | value as u8);
        return;
    }
    out.push(first_byte_flags | max_prefix as u8);
    let mut v = value - max_prefix;
    while v >= 128 {
        out.push((v as u8 & 0x7f) | 0x80);
        v >>= 7;
    }
    out.push(v as u8);
}

fn encode_string(out: &mut Vec<u8>, s: &[u8]) {
    encode_integer(out, s.len(), 7, 0);
    out.extend_from_slice(s);
}

/// Encode a header block using literal representations without indexing.
pub fn encode(headers: &[(String, String)]) -> Vec<u8> {
    let mut out = Vec::new();
    for (name, value) in headers {
        let name_lower = name.to_ascii_lowercase();
        let mut exact = None;
        let mut name_idx = None;
        for (i, (n, v)) in STATIC_TABLE.iter().enumerate() {
            if *n == name_lower {
                if name_idx.is_none() {
                    name_idx = Some(i + 1);
                }
                if *v == value {
                    exact = Some(i + 1);
                    break;
                }
            }
        }
        if let Some(idx) = exact {
            encode_integer(&mut out, idx, 7, 0x80);
            continue;
        }
        match name_idx {
            Some(idx) => encode_integer(&mut out, idx, 4, 0),
            None => {
                out.push(0);
                encode_string(&mut out, name_lower.as_bytes());
            }
        }
        encode_string(&mut out, value.as_bytes());
    }
    out
}
