//! A small HTTP/2 client used for `--http2`.
use crate::client::{
    absolute_form, origin_form, Client, ClientError, Connection, ConnectionTime, HttpVersion, Limits,
    RequestResult, Response,
};
use crate::hpack;
use std::collections::HashMap;
use std::time::Instant;
use url::Url;

const PREFACE: &[u8] = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n";
const FRAME_DATA: u8 = 0;
const FRAME_HEADERS: u8 = 1;
const FRAME_PRIORITY: u8 = 2;
const FRAME_RST_STREAM: u8 = 3;
const FRAME_SETTINGS: u8 = 4;
const FRAME_PUSH_PROMISE: u8 = 5;
const FRAME_PING: u8 = 6;
const FRAME_GOAWAY: u8 = 7;
const FRAME_WINDOW_UPDATE: u8 = 8;
const FRAME_CONTINUATION: u8 = 9;

const FLAG_END_STREAM: u8 = 0x1;
const FLAG_ACK: u8 = 0x1;
const FLAG_END_HEADERS: u8 = 0x4;
const FLAG_PADDED: u8 = 0x8;
const FLAG_PRIORITY: u8 = 0x20;

const OUR_MAX_FRAME_SIZE: usize = 16384;
const OUR_INITIAL_WINDOW: u32 = 0x7fff_ffff;

pub struct H2Stream {
    pub start: Instant,
    pub start_latency_correction: Option<Instant>,
    pub connection_time: Option<ConnectionTime>,
    pub first_byte: Option<Instant>,
    pub status: u16,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
    pub len_bytes: usize,
    pub url_path: String,
    pub deadline: Option<Instant>,
    pub send_window: i64,
    pub pending_body: Vec<u8>,
    pub body_sent: usize,
    pub body_end_sent: bool,
    pub header_block: Vec<u8>,
    pub header_end_stream: bool,
    pub done: bool,
    pub keep_body: bool,
}

pub struct H2Connection {
    pub conn: Connection,
    decoder: hpack::Decoder,
    next_stream_id: u32,
    peer_max_frame_size: usize,
    peer_initial_window: i64,
    conn_send_window: i64,
    pub streams: HashMap<u32, H2Stream>,
    pub closed: bool,
    pub goaway: bool,
}

fn h2err() -> ClientError {
    ClientError::Http2("http2 error".to_string())
}

fn conn_err() -> ClientError {
    ClientError::Http2("connection error".to_string())
}

fn frame_header(len: usize, typ: u8, flags: u8, stream_id: u32) -> [u8; 9] {
    [
        (len >> 16) as u8,
        (len >> 8) as u8,
        len as u8,
        typ,
        flags,
        (stream_id >> 24) as u8 & 0x7f,
        (stream_id >> 16) as u8,
        (stream_id >> 8) as u8,
        stream_id as u8,
    ]
}

impl H2Connection {
    pub fn new(mut conn: Connection, limits: &Limits) -> Result<Self, ClientError> {
        let mut out = Vec::new();
        out.extend_from_slice(PREFACE);
        // SETTINGS: ENABLE_PUSH=0, INITIAL_WINDOW_SIZE, MAX_FRAME_SIZE
        let mut settings = Vec::new();
        settings.extend_from_slice(&[0, 2, 0, 0, 0, 0]);
        settings.extend_from_slice(&[0, 4]);
        settings.extend_from_slice(&OUR_INITIAL_WINDOW.to_be_bytes());
        settings.extend_from_slice(&[0, 5]);
        settings.extend_from_slice(&(OUR_MAX_FRAME_SIZE as u32).to_be_bytes());
        out.extend_from_slice(&frame_header(settings.len(), FRAME_SETTINGS, 0, 0));
        out.extend_from_slice(&settings);
        // Connection-level window update
        let inc: u32 = OUR_INITIAL_WINDOW - 65535;
        out.extend_from_slice(&frame_header(4, FRAME_WINDOW_UPDATE, 0, 0));
        out.extend_from_slice(&inc.to_be_bytes());
        conn.write_all_pub(&out, limits)?;
        Ok(H2Connection {
            conn,
            decoder: hpack::Decoder::default(),
            next_stream_id: 1,
            peer_max_frame_size: 16384,
            peer_initial_window: 65535,
            conn_send_window: 65535,
            streams: HashMap::new(),
            closed: false,
            goaway: false,
        })
    }

    pub fn in_flight(&self) -> usize {
        self.streams.len()
    }

    /// Start a new stream. Returns the stream id.
    pub fn send_request(
        &mut self,
        method: &str,
        url: &Url,
        headers: &[(String, String)],
        body: Option<&[u8]>,
        mut stream: H2Stream,
        limits: &Limits,
    ) -> Result<u32, ClientError> {
        if self.closed || self.goaway {
            return Err(conn_err());
        }
        let id = self.next_stream_id;
        self.next_stream_id += 2;
        let mut all: Vec<(String, String)> = vec![
            (":method".to_string(), method.to_string()),
            (":scheme".to_string(), url.scheme().to_string()),
            (":authority".to_string(), url.authority().to_string()),
            (":path".to_string(), origin_form(url)),
        ];
        for (k, v) in headers {
            if k == "host" || k == "connection" {
                continue;
            }
            all.push((k.clone(), v.clone()));
        }
        let has_body = body.map(|b| !b.is_empty()).unwrap_or(false);
        if has_body && !all.iter().any(|(k, _)| k == "content-length") {
            all.push(("content-length".to_string(), body.unwrap().len().to_string()));
        }
        let block = hpack::encode(&all);
        let mut out = Vec::new();
        let mut flags = FLAG_END_HEADERS;
        if !has_body {
            flags |= FLAG_END_STREAM;
        }
        // split into HEADERS + CONTINUATION if needed
        let max = self.peer_max_frame_size;
        if block.len() <= max {
            out.extend_from_slice(&frame_header(block.len(), FRAME_HEADERS, flags, id));
            out.extend_from_slice(&block);
        } else {
            let mut first = true;
            let mut pos = 0;
            while pos < block.len() {
                let end = (pos + max).min(block.len());
                let last = end == block.len();
                let typ = if first { FRAME_HEADERS } else { FRAME_CONTINUATION };
                let mut f = 0u8;
                if first && !has_body {
                    f |= FLAG_END_STREAM;
                }
                if last {
                    f |= FLAG_END_HEADERS;
                }
                out.extend_from_slice(&frame_header(end - pos, typ, f, id));
                out.extend_from_slice(&block[pos..end]);
                first = false;
                pos = end;
            }
        }
        stream.send_window = self.peer_initial_window;
        stream.body_end_sent = !has_body;
        if has_body {
            stream.pending_body = body.unwrap().to_vec();
        }
        self.conn.write_all_pub(&out, limits)?;
        self.streams.insert(id, stream);
        if has_body {
            self.flush_bodies(limits)?;
        }
        Ok(id)
    }

    /// Send as much pending body data as flow control allows.
    fn flush_bodies(&mut self, limits: &Limits) -> Result<(), ClientError> {
        let mut out = Vec::new();
        let max = self.peer_max_frame_size;
        let mut ids: Vec<u32> = self.streams.keys().copied().collect();
        ids.sort();
        for id in ids {
            let conn_window = self.conn_send_window;
            let st = self.streams.get_mut(&id).unwrap();
            if st.body_end_sent {
                continue;
            }
            let mut conn_window = conn_window;
            while st.body_sent < st.pending_body.len() {
                let remaining = st.pending_body.len() - st.body_sent;
                let allowed = remaining.min(max).min(st.send_window.max(0) as usize).min(conn_window.max(0) as usize);
                if allowed == 0 {
                    break;
                }
                let end = st.body_sent + allowed;
                let last = end == st.pending_body.len();
                let flags = if last { FLAG_END_STREAM } else { 0 };
                out.extend_from_slice(&frame_header(allowed, FRAME_DATA, flags, id));
                out.extend_from_slice(&st.pending_body[st.body_sent..end]);
                st.body_sent = end;
                st.send_window -= allowed as i64;
                conn_window -= allowed as i64;
                if last {
                    st.body_end_sent = true;
                }
            }
            if st.body_sent == st.pending_body.len() && !st.body_end_sent {
                // empty body with content-length header: send an empty END_STREAM frame
                out.extend_from_slice(&frame_header(0, FRAME_DATA, FLAG_END_STREAM, id));
                st.body_end_sent = true;
            }
            self.conn_send_window = conn_window;
        }
        if !out.is_empty() {
            self.conn.write_all_pub(&out, limits)?;
        }
        Ok(())
    }

    fn read_exact(&mut self, n: usize, limits: &Limits) -> Result<Vec<u8>, ClientError> {
        while self.conn.buffered_pub().len() < n {
            let got = self.conn.fill_pub(limits)?;
            if got == 0 {
                self.closed = true;
                return Err(conn_err());
            }
        }
        let data = self.conn.buffered_pub()[..n].to_vec();
        self.conn.consume_pub(n);
        Ok(data)
    }

    /// Read and process one frame. Returns the ids of streams that completed.
    pub fn read_frame(&mut self, limits: &Limits) -> Result<Vec<u32>, ClientError> {
        let header = self.read_exact(9, limits)?;
        let len = ((header[0] as usize) << 16) | ((header[1] as usize) << 8) | header[2] as usize;
        let typ = header[3];
        let flags = header[4];
        let stream_id = u32::from_be_bytes([header[5] & 0x7f, header[6], header[7], header[8]]);
        if len > OUR_MAX_FRAME_SIZE {
            self.closed = true;
            return Err(h2err());
        }
        let payload = self.read_exact(len, limits)?;
        let mut completed = Vec::new();
        match typ {
            FRAME_DATA => {
                if stream_id == 0 {
                    self.closed = true;
                    return Err(h2err());
                }
                let mut data: &[u8] = &payload;
                if flags & FLAG_PADDED != 0 {
                    if data.is_empty() {
                        self.closed = true;
                        return Err(h2err());
                    }
                    let pad = data[0] as usize;
                    if pad + 1 > data.len() {
                        self.closed = true;
                        return Err(h2err());
                    }
                    data = &data[1..data.len() - pad];
                }
                let now = Instant::now();
                if let Some(st) = self.streams.get_mut(&stream_id) {
                    if !data.is_empty() && st.first_byte.is_none() {
                        st.first_byte = Some(now);
                    }
                    st.len_bytes += data.len();
                    if st.keep_body {
                        st.body.extend_from_slice(data);
                    }
                    if flags & FLAG_END_STREAM != 0 {
                        st.done = true;
                        completed.push(stream_id);
                    }
                }
                if len > 0 {
                    // replenish the connection window
                    let mut out = Vec::new();
                    out.extend_from_slice(&frame_header(4, FRAME_WINDOW_UPDATE, 0, 0));
                    out.extend_from_slice(&(len as u32).to_be_bytes());
                    self.conn.write_all_pub(&out, limits)?;
                }
            }
            FRAME_HEADERS | FRAME_CONTINUATION => {
                if stream_id == 0 {
                    self.closed = true;
                    return Err(h2err());
                }
                let mut data: &[u8] = &payload;
                if typ == FRAME_HEADERS {
                    if flags & FLAG_PADDED != 0 {
                        if data.is_empty() {
                            self.closed = true;
                            return Err(h2err());
                        }
                        let pad = data[0] as usize;
                        if pad + 1 > data.len() {
                            self.closed = true;
                            return Err(h2err());
                        }
                        data = &data[1..data.len() - pad];
                    }
                    if flags & FLAG_PRIORITY != 0 {
                        if data.len() < 5 {
                            self.closed = true;
                            return Err(h2err());
                        }
                        data = &data[5..];
                    }
                }
                let end_headers = flags & FLAG_END_HEADERS != 0;
                let end_stream = typ == FRAME_HEADERS && flags & FLAG_END_STREAM != 0;
                let block = if let Some(st) = self.streams.get_mut(&stream_id) {
                    st.header_block.extend_from_slice(data);
                    if end_stream {
                        st.header_end_stream = true;
                    }
                    if end_headers {
                        Some(std::mem::take(&mut st.header_block))
                    } else {
                        None
                    }
                } else {
                    // unknown stream: still need to decode to keep HPACK state in sync
                    if end_headers {
                        let _ = self.decoder.decode(data);
                    }
                    None
                };
                if let Some(block) = block {
                    let headers = self.decoder.decode(&block).map_err(|_| {
                        self.closed = true;
                        h2err()
                    })?;
                    let st = self.streams.get_mut(&stream_id).unwrap();
                    let status: Option<u16> = headers
                        .iter()
                        .find(|(k, _)| k == ":status")
                        .and_then(|(_, v)| v.parse().ok());
                    match status {
                        Some(s) if (100..200).contains(&s) => {
                            // informational; wait for the final response
                        }
                        Some(s) => {
                            st.status = s;
                            st.headers = headers.into_iter().filter(|(k, _)| !k.starts_with(':')).collect();
                        }
                        None => {
                            // trailers
                        }
                    }
                    if st.header_end_stream {
                        st.done = true;
                        completed.push(stream_id);
                    }
                }
            }
            FRAME_PRIORITY => {}
            FRAME_RST_STREAM => {
                if let Some(mut st) = self.streams.remove(&stream_id) {
                    st.done = true;
                    // Report as an HTTP/2 error
                    st.status = 0;
                    self.streams.insert(stream_id, st);
                    completed.push(stream_id);
                    return Err(ClientError::Http2(format!("rst:{}", stream_id)));
                }
            }
            FRAME_SETTINGS => {
                if stream_id != 0 {
                    self.closed = true;
                    return Err(h2err());
                }
                if flags & FLAG_ACK == 0 {
                    if len % 6 != 0 {
                        self.closed = true;
                        return Err(h2err());
                    }
                    let mut i = 0;
                    while i + 6 <= payload.len() {
                        let id = u16::from_be_bytes([payload[i], payload[i + 1]]);
                        let val = u32::from_be_bytes([payload[i + 2], payload[i + 3], payload[i + 4], payload[i + 5]]);
                        match id {
                            4 => {
                                let delta = val as i64 - self.peer_initial_window;
                                self.peer_initial_window = val as i64;
                                for st in self.streams.values_mut() {
                                    st.send_window += delta;
                                }
                            }
                            5 => {
                                if (16384..=16_777_215).contains(&val) {
                                    self.peer_max_frame_size = val as usize;
                                }
                            }
                            _ => {}
                        }
                        i += 6;
                    }
                    let out = frame_header(0, FRAME_SETTINGS, FLAG_ACK, 0);
                    self.conn.write_all_pub(&out, limits)?;
                    self.flush_bodies(limits)?;
                }
            }
            FRAME_PUSH_PROMISE => {
                self.closed = true;
                return Err(h2err());
            }
            FRAME_PING => {
                if flags & FLAG_ACK == 0 {
                    let mut out = Vec::new();
                    out.extend_from_slice(&frame_header(payload.len(), FRAME_PING, FLAG_ACK, 0));
                    out.extend_from_slice(&payload);
                    self.conn.write_all_pub(&out, limits)?;
                }
            }
            FRAME_GOAWAY => {
                self.goaway = true;
                if payload.len() >= 8 {
                    let last = u32::from_be_bytes([payload[0] & 0x7f, payload[1], payload[2], payload[3]]);
                    let error_code = u32::from_be_bytes([payload[4], payload[5], payload[6], payload[7]]);
                    if error_code != 0 {
                        self.closed = true;
                        return Err(h2err());
                    }
                    let _ = last;
                }
            }
            FRAME_WINDOW_UPDATE => {
                if payload.len() != 4 {
                    self.closed = true;
                    return Err(h2err());
                }
                let inc = u32::from_be_bytes([payload[0] & 0x7f, payload[1], payload[2], payload[3]]) as i64;
                if stream_id == 0 {
                    self.conn_send_window += inc;
                } else if let Some(st) = self.streams.get_mut(&stream_id) {
                    st.send_window += inc;
                }
                self.flush_bodies(limits)?;
            }
            _ => {}
        }
        Ok(completed)
    }

    pub fn cancel_stream(&mut self, id: u32, limits: &Limits) {
        let mut out = Vec::new();
        out.extend_from_slice(&frame_header(4, FRAME_RST_STREAM, 0, id));
        out.extend_from_slice(&8u32.to_be_bytes()); // CANCEL
        let _ = self.conn.write_all_pub(&out, limits);
        self.streams.remove(&id);
    }
}

fn new_stream(start: Instant, slc: Option<Instant>, ct: Option<ConnectionTime>, url: &Url, deadline: Option<Instant>, keep_body: bool) -> H2Stream {
    H2Stream {
        start,
        start_latency_correction: slc,
        connection_time: ct,
        first_byte: None,
        status: 0,
        headers: Vec::new(),
        body: Vec::new(),
        len_bytes: 0,
        url_path: origin_form(url),
        deadline,
        send_window: 0,
        pending_body: Vec::new(),
        body_sent: 0,
        body_end_sent: false,
        header_block: Vec::new(),
        header_end_stream: false,
        done: false,
        keep_body,
    }
}

fn stream_result(st: H2Stream, end: Instant) -> RequestResult {
    RequestResult {
        start_latency_correction: st.start_latency_correction,
        start: st.start,
        connection_time: st.connection_time,
        first_byte: st.first_byte,
        end,
        status: st.status,
        len_bytes: st.len_bytes,
        url_path: st.url_path,
    }
}

impl Client {
    fn ensure_h2(&mut self, url: &Url, limits: &Limits) -> Result<Option<ConnectionTime>, ClientError> {
        let need = match &self.h2 {
            Some(h) => h.closed || h.goaway,
            None => true,
        };
        if need {
            self.h2 = None;
            let (conn, ct) = self.connect_for_url(url, limits)?;
            let h2 = H2Connection::new(conn, limits)?;
            self.h2 = Some(h2);
            Ok(Some(ct))
        } else {
            Ok(None)
        }
    }

    /// Limits used for reading frames: the earliest deadline over in-flight streams.
    fn h2_read_limits(&self) -> Limits {
        let mut earliest: Option<Instant> = None;
        if let Some(h2) = &self.h2 {
            for st in h2.streams.values() {
                if let Some(d) = st.deadline {
                    earliest = Some(earliest.map(|e: Instant| e.min(d)).unwrap_or(d));
                }
            }
        }
        Limits {
            request_deadline: earliest,
            global_deadline: None,
        }
    }

    /// Start a new HTTP/2 stream for a generated URL.
    pub fn h2_start(&mut self, slc: Option<Instant>) -> Result<u32, (Option<RequestResult>, ClientError)> {
        let url = self
            .config
            .url_generator
            .generate(&mut self.rng)
            .map_err(|e| (None, ClientError::UrlGen(e)))?;
        let start = Instant::now();
        let deadline = self.config.timeout.map(|t| start + t);
        let limits = Limits {
            request_deadline: deadline,
            global_deadline: None,
        };
        let ct = self.ensure_h2(&url, &limits).map_err(|e| (None, e))?;
        let body = self.pick_body();
        let headers = self.build_headers(&url, false, body.as_deref());
        let st = new_stream(start, slc, ct, &url, deadline, false);
        let method = self.config.method.clone();
        let h2 = self.h2.as_mut().unwrap();
        h2.send_request(&method, &url, &headers, body.as_deref(), st, &limits)
            .map_err(|e| (None, e))
    }

    /// Wait for frames until at least one stream completes or fails.
    /// Returns the results of completed streams.
    pub fn h2_poll(&mut self) -> Vec<Result<RequestResult, ClientError>> {
        let mut out = Vec::new();
        let limits = self.h2_read_limits();
        // Expire timed out streams first
        let now = Instant::now();
        let mut expired = Vec::new();
        if let Some(h2) = &self.h2 {
            for (id, st) in &h2.streams {
                if let Some(d) = st.deadline {
                    if now >= d {
                        expired.push(*id);
                    }
                }
            }
        }
        if !expired.is_empty() {
            let h2 = self.h2.as_mut().unwrap();
            for id in expired {
                h2.cancel_stream(id, &limits);
                out.push(Err(ClientError::Timeout));
            }
            return out;
        }
        let h2 = match self.h2.as_mut() {
            Some(h) => h,
            None => return out,
        };
        match h2.read_frame(&limits) {
            Ok(completed) => {
                let end = Instant::now();
                for id in completed {
                    if let Some(st) = h2.streams.remove(&id) {
                        out.push(Ok(stream_result(st, end)));
                    }
                }
            }
            Err(ClientError::Http2(ref m)) if m.starts_with("rst:") => {
                let id: u32 = m[4..].parse().unwrap_or(0);
                h2.streams.remove(&id);
                out.push(Err(h2err()));
            }
            Err(ClientError::Timeout) | Err(ClientError::Deadline) => {
                // handled on the next poll by the expiry check
                let now = Instant::now();
                let mut expired = Vec::new();
                for (id, st) in &h2.streams {
                    if let Some(d) = st.deadline {
                        if now >= d {
                            expired.push(*id);
                        }
                    }
                }
                if expired.is_empty() {
                    // spurious timeout; nothing to do
                } else {
                    for id in expired {
                        h2.cancel_stream(id, &limits);
                        out.push(Err(ClientError::Timeout));
                    }
                }
            }
            Err(e) => {
                // connection failure: all in-flight streams fail
                h2.closed = true;
                let n = h2.streams.len();
                h2.streams.clear();
                let first_msg = e.to_string();
                for i in 0..n {
                    if i == 0 {
                        out.push(Err(ClientError::Http2(first_msg.clone())));
                    } else {
                        out.push(Err(conn_err()));
                    }
                }
                if n == 0 {
                    out.push(Err(ClientError::Http2(first_msg)));
                }
                self.h2 = None;
            }
        }
        out
    }

    pub fn h2_in_flight(&self) -> usize {
        self.h2.as_ref().map(|h| h.in_flight()).unwrap_or(0)
    }

    /// Single request used by the sequential worker loop (p = 1).
    pub fn work_http2(
        &mut self,
        _start: Instant,
        start_latency_correction: Option<Instant>,
        _limits: &Limits,
    ) -> Result<RequestResult, ClientError> {
        match self.h2_start(start_latency_correction) {
            Ok(_) => {}
            Err((_, e)) => return Err(e),
        }
        loop {
            let mut results = self.h2_poll();
            if let Some(r) = results.pop() {
                return r;
            }
            if self.h2.is_none() {
                return Err(conn_err());
            }
        }
    }

    pub fn debug_http2(
        &mut self,
        url: &Url,
        headers: &[(String, String)],
        body: Option<&[u8]>,
        limits: &Limits,
    ) -> Result<Response, ClientError> {
        self.ensure_h2(url, limits)?;
        let start = Instant::now();
        let st = new_stream(start, None, None, url, None, true);
        let method = self.config.method.clone();
        let id = {
            let h2 = self.h2.as_mut().unwrap();
            h2.send_request(&method, url, headers, body, st, limits)?
        };
        loop {
            let h2 = self.h2.as_mut().unwrap();
            let completed = h2.read_frame(limits)?;
            if completed.contains(&id) {
                let st = h2.streams.remove(&id).unwrap();
                return Ok(Response {
                    version: HttpVersion::Http2,
                    status: st.status,
                    headers: st.headers,
                    body: st.body,
                    keep_alive: true,
                });
            }
        }
    }
}

