/// Source of "permission to send a request" tokens.
pub enum TokenSource {
    Counter { counter: Arc<AtomicUsize>, n: usize },
    Deadline(Instant),
    Channel { rx: Receiver<Instant>, deadline: Option<Instant>, latency_correction: bool },
}

impl TokenSource {
    /// Blocking: returns `None` when there is no more work.
    fn take(&self, stop: &AtomicBool) -> Option<Option<Instant>> {
        if stop.load(Ordering::Relaxed) {
            return None;
        }
        match self {
            TokenSource::Counter { counter, n } => {
                if counter.fetch_add(1, Ordering::Relaxed) >= *n {
                    None
                } else {
                    Some(None)
                }
            }
            TokenSource::Deadline(d) => {
                if Instant::now() >= *d {
                    None
                } else {
                    Some(None)
                }
            }
            TokenSource::Channel { rx, deadline, latency_correction } => {
                let t = match deadline {
                    Some(d) => {
                        let now = Instant::now();
                        if now >= *d {
                            return None;
                        }
                        rx.recv_timeout(*d - now).ok()?
                    }
                    None => rx.recv().ok()?,
                };
                Some(if *latency_correction { None } else { Some(t) })
            }
        }
    }

    /// Non-blocking variant: `Err(())` when no token is available right now.
    fn try_take(&self, stop: &AtomicBool) -> Result<Option<Option<Instant>>, ()> {
        if stop.load(Ordering::Relaxed) {
            return Ok(None);
        }
        match self {
            TokenSource::Counter { .. } | TokenSource::Deadline(_) => Ok(self.take(stop)),
            TokenSource::Channel { rx, deadline, latency_correction } => {
                if let Some(d) = deadline {
                    if Instant::now() >= *d {
                        return Ok(None);
                    }
                }
                match rx.try_recv() {
                    Ok(t) => Ok(Some(if *latency_correction { None } else { Some(t) })),
                    Err(crossbeam_channel::TryRecvError::Empty) => Err(()),
                    Err(crossbeam_channel::TryRecvError::Disconnected) => Ok(None),
                }
            }
        }
    }
}

/// Worker loop for HTTP/2: one connection with up to `parallel` concurrent streams.
fn h2_worker(mut client: Client, tokens: TokenSource, parallel: usize, tx: Sender<Report>, stop: Arc<AtomicBool>) {
    let parallel = parallel.max(1);
    let mut exhausted = false;
    loop {
        // Start new streams while there is capacity.
        while !exhausted && client.h2_in_flight() < parallel {
            let token = if client.h2_in_flight() == 0 {
                tokens.take(&stop)
            } else {
                match tokens.try_take(&stop) {
                    Ok(t) => t,
                    Err(()) => break,
                }
            };
            match token {
                None => {
                    exhausted = true;
                    break;
                }
                Some(slc) => {
                    if let Err((_, e)) = client.h2_start(slc) {
                        if tx.send(Err(e)).is_err() {
                            return;
                        }
                    }
                }
            }
        }
        if client.h2_in_flight() == 0 {
            if exhausted {
                break;
            }
            continue;
        }
        for r in client.h2_poll() {
            if tx.send(r).is_err() {
                return;
            }
        }
        if stop.load(Ordering::Relaxed) {
            break;
        }
    }
}
