fn spawn_scheduler(
    rate: Rate,
    mode: Mode,
    deadline: Option<Instant>,
    stop: Arc<AtomicBool>,
    token_tx: Sender<Instant>,
) -> JoinHandle<()> {
    std::thread::spawn(move || {
        let mut sent = 0usize;
        let limit = match mode {
            Mode::Count(n) => Some(n),
            Mode::Duration(_) => None,
        };
        let sched_start = Instant::now();
        match rate {
            Rate::Qps(qps) => {
                let mut i: u64 = 0;
                loop {
                    if stop.load(Ordering::Relaxed) {
                        break;
                    }
                    if let Some(n) = limit {
                        if sent >= n {
                            break;
                        }
                    }
                    let t = sched_start + Duration::from_secs_f64(i as f64 / qps);
                    if let Some(d) = deadline {
                        if t >= d {
                            break;
                        }
                    }
                    sleep_until(t);
                    if stop.load(Ordering::Relaxed) {
                        break;
                    }
                    if token_tx.send(Instant::now()).is_err() {
                        break;
                    }
                    sent += 1;
                    i += 1;
                }
            }
            Rate::Burst { delay, rate } => {
                let mut next = sched_start + delay;
                'outer: loop {
                    if stop.load(Ordering::Relaxed) {
                        break;
                    }
                    if let Some(d) = deadline {
                        if next >= d {
                            break;
                        }
                    }
                    sleep_until(next);
                    next += delay;
                    let now = Instant::now();
                    for _ in 0..rate {
                        if let Some(n) = limit {
                            if sent >= n {
