fn spawn_http2(setup: WorkSetup, report_tx: Sender<Report>, deadline: Option<Instant>) -> Vec<JoinHandle<()>> {
    let mut handles = Vec::new();
    let token_rx: Option<Receiver<Instant>> = match setup.rate {
        Rate::Unlimited => None,
        Rate::Qps(_) | Rate::Burst { .. } => {
            let (token_tx, token_rx) = crossbeam_channel::unbounded();
            handles.push(spawn_scheduler(setup.rate, setup.mode, deadline, setup.stop.clone(), token_tx));
            Some(token_rx)
        }
    };
    let counter = Arc::new(AtomicUsize::new(0));
    for _ in 0..setup.n_connections {
        let config = setup.config.clone();
        let tx = report_tx.clone();
        let stop = setup.stop.clone();
        let tokens = match (&token_rx, setup.mode) {
            (Some(rx), _) => TokenSource::Channel {
                rx: rx.clone(),
                deadline,
                latency_correction: setup.latency_correction,
            },
            (None, Mode::Count(n)) => TokenSource::Counter {
                counter: counter.clone(),
                n,
            },
            (None, Mode::Duration(_)) => TokenSource::Deadline(deadline.unwrap()),
        };
        let parallel = setup.n_parallel;
        handles.push(std::thread::spawn(move || {
            let client = Client::new(config);
            h2_worker(client, tokens, parallel, tx, stop);
        }));
    }
    handles
}

fn spawn_scheduler(
    rate: Rate,
    mode: Mode,
    deadline: Option<Instant>,
    stop: Arc<AtomicBool>,
    token_tx: Sender<Instant>,
) -> JoinHandle<()> {
    std::thread::spawn(move || {
        let mut sent = 0usize;
        let limit = match mode {
            Mode::Count(n) => Some(n),
            Mode::Duration(_) => None,
        };
        let sched_start = Instant::now();
        match rate {
            Rate::Qps(qps) => {
                let mut i: u64 = 0;
                loop {
                    if stop.load(Ordering::Relaxed) {
                        break;
                    }
                    if let Some(n) = limit {
                        if sent >= n {
                            break;
                        }
                    }
                    let t = sched_start + Duration::from_secs_f64(i as f64 / qps);
                    if let Some(d) = deadline {
                        if t >= d {
                            break;
                        }
                    }
                    sleep_until(t);
                    if stop.load(Ordering::Relaxed) {
                        break;
                    }
                    if token_tx.send(Instant::now()).is_err() {
                        break;
                    }
                    sent += 1;
                    i += 1;
                }
            }
            Rate::Burst { delay, rate } => {
                let mut next = sched_start + delay;
                'outer: loop {
                    if stop.load(Ordering::Relaxed) {
                        break;
                    }
                    if let Some(d) = deadline {
                        if next >= d {
                            break;
                        }
                    }
                    sleep_until(next);
                    next += delay;
                    let now = Instant::now();
                    for _ in 0..rate {
                        if let Some(n) = limit {
                            if sent >= n {
                                break 'outer;
                            }
                        }
                        if token_tx.send(now).is_err() {
                            break 'outer;
                        }
                        sent += 1;
                    }
                    if let Some(n) = limit {
                        if sent >= n {
                            break;
                        }
                    }
                }
            }
            Rate::Unlimited => {}
        }
        drop(token_tx);
    })
}
