fn status_color(status: u16) -> Color {
    match status {
        200..=299 => Color::Green,
        400..=499 => Color::Yellow,
        500..=599 => Color::Red,
        _ => Color::White,
    }
}

fn success_rate_color(rate: f64) -> Color {
    if rate >= 100.0 {
        Color::Green
    } else if rate >= 99.0 {
        Color::Yellow
    } else {
        Color::Red
    }
}
""")

