new = '''pub fn print_text<W: Write>(
    w: &mut W,
    res: &ResultData,
    total_duration: Duration,
    time_unit: Option<TimeUnit>,
    stats_success_breakdown: bool,
    color: bool,
) -> std::io::Result<()> {
    let st = Styler { enabled: color };
    let durations = res.durations();
    let total = total_duration.as_secs_f64();
    let slowest = fmax(durations.iter().copied());
    let fastest = fmin(durations.iter().copied());
    let average = fmean(&durations);
    let unit = time_unit.unwrap_or_else(|| TimeUnit::from_secs(slowest));
    let total_requests = res.total_requests();
    let success_rate = res.success.len() as f64 / res.len_for_success_rate() as f64 * 100.0;
    let rps = total_requests as f64 / total;
    let total_bytes = res.total_bytes();

    writeln!(w, "{}", st.heading("Summary:"))?;
    writeln!(
        w,
        "{}",
        st.colored_bold(
            &format!("  Success rate:\\t{:.2}%", success_rate),
            success_rate_color(success_rate)
        )
    )?;
    writeln!(w, "  Total:\\t{:.4} {}", unit.convert(total), unit.name())?;
    writeln!(
        w,
        "{}",
        st.colored(&format!("  Slowest:\\t{:.4} {}", unit.convert(slowest), unit.name()), Color::Yellow)
    )?;
    writeln!(
        w,
        "{}",
        st.colored(&format!("  Fastest:\\t{:.4} {}", unit.convert(fastest), unit.name()), Color::Green)
    )?;
    writeln!(
        w,
        "{}",
        st.colored(&format!("  Average:\\t{:.4} {}", unit.convert(average), unit.name()), Color::Cyan)
    )?;
    writeln!(w, "  Requests/sec:\\t{:.4}", rps)?;
    writeln!(w)?;
    writeln!(w, "  Total data:\\t{}", format_bytes(total_bytes as f64))?;
    if res.success.is_empty() {
        writeln!(w, "  Size/request:\\tNaN")?;
    } else {
        writeln!(
            w,
            "  Size/request:\\t{}",
            format_bytes((total_bytes / res.success.len()) as f64)
        )?;
    }
    writeln!(w, "  Size/sec:\\t{}", format_bytes(total_bytes as f64 / total))?;
    writeln!(w)?;
    writeln!(w, "{}", st.heading("Response time histogram:"))?;
    print_histogram(w, &durations, unit, st)?;
    writeln!(w)?;
    writeln!(w, "{}", st.heading("Response time distribution:"))?;
    let mut sorted = durations.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
    print_distribution(w, &sorted, unit, st)?;
    writeln!(w)?;

    if stats_success_breakdown {
        let succ_d: Vec<f64> = res
            .success
            .iter()
            .filter(|r| (200..300).contains(&r.status))
            .map(|r| r.duration().as_secs_f64())
            .collect();
        let mut not_succ_d: Vec<f64> = res
            .success
            .iter()
            .filter(|r| (400..600).contains(&r.status))
            .map(|r| r.duration().as_secs_f64())
            .collect();
        writeln!(w, "{}", st.heading("Response time histogram (2xx only):"))?;
        print_histogram(w, &succ_d, unit, st)?;
        writeln!(w)?;
        writeln!(w, "{}", st.heading("Response time distribution (2xx only):"))?;
        let mut s = succ_d.clone();
        s.sort_by(|a, b| a.partial_cmp(b).unwrap());
        print_distribution(w, &s, unit, st)?;
        writeln!(w)?;
        writeln!(w, "{}", st.heading("Response time histogram (4xx + 5xx only):"))?;
        print_histogram(w, &not_succ_d, unit, st)?;
        writeln!(w)?;
        writeln!(w, "{}", st.heading("Response time distribution (4xx + 5xx only):"))?;
        not_succ_d.sort_by(|a, b| a.partial_cmp(b).unwrap());
        print_distribution(w, &not_succ_d, unit, st)?;
        writeln!(w)?;
    }

    writeln!(w)?;
    writeln!(w, "{}", st.heading("Details (average, fastest, slowest):"))?;
    let (dialup, dns) = details(res);
    writeln!(
        w,
        "  DNS+dialup:\\t{:.4} {}, {:.4} {}, {:.4} {}",
        unit.convert(fmean(&dialup)),
        unit.name(),
        unit.convert(fmin(dialup.iter().copied())),
        unit.name(),
        unit.convert(fmax(dialup.iter().copied())),
        unit.name()
    )?;
    writeln!(
        w,
        "  DNS-lookup:\\t{:.4} {}, {:.4} {}, {:.4} {}",
        unit.convert(fmean(&dns)),
        unit.name(),
        unit.convert(fmin(dns.iter().copied())),
        unit.name(),
        unit.convert(fmax(dns.iter().copied())),
        unit.name()
    )?;
    writeln!(w)?;
    writeln!(w, "{}", st.heading("Status code distribution:"))?;
    for (code, count) in res.status_code_distribution() {
        writeln!(
            w,
            "{}",
            st.colored(&format!("  [{}] {} responses", code, count), status_color(code))
        )?;
    }
    let errors = res.error_distribution_sorted();
    if !errors.is_empty() {
        writeln!(w)?;
        writeln!(w, "Error distribution:")?;
        for (msg, count) in errors {
            writeln!(w, "  [{}] {}", count, msg)?;
        }
    }
    Ok(())
}

